                .default_value("github"),
        )
        .arg(output_path.clone())
        .arg(site_path.clone());

    let generate = Command::new("generate")
        .about("Generate infrastructure files for oranda sites")
        .arg_required_else_help(true)
        .subcommand_required(true)
        .subcommand(ci)
        .arg(output_path)
        .arg(site_path);

    Command::new("oranda")
        .version("0.6.5")
        .about("\u{1f381} generate beautiful landing pages for your projects")
        .arg_required_else_help(true)
        .subcommand_required(true)
        .arg(verbose)
        .arg(output_format)
        .subcommand(build)
        .subcommand(dev)
        .subcommand(serve)
        .subcommand(generate)
}
