//! Minimal terminal size detection used by clap's `wrap_help` feature.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Height(pub u16);

/// Returns the size of the terminal attached to stdout, if any.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of_fd(libc::STDOUT_FILENO)
}

/// Returns the size of the terminal attached to the given raw fd, if any.
pub fn terminal_size_of_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == -1 {
            return None;
        }
        if ws.ws_row > 0 && ws.ws_col > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}
EOF
