/// Whether a direct (no intervening spaces) break between `a` and `b` is
/// prohibited by the pair rules.
fn pair_prohibited(a: Lb, b: Lb) -> bool {
    use Lb::*;
    // LB11
    if a == Wj || b == Wj {
        return true;
    }
    // LB12
    if a == Gl {
        return true;
    }
    // LB12a
    if b == Gl && !matches!(a, Sp | Ba | Hy) {
        return true;
    }
    // LB13
    if matches!(b, Cl | Cp | Ex | Is | Sy) {
        return true;
    }
    // LB14
    if a == Op {
        return true;
    }
    // LB15
    if a == Qu && b == Op {
        return true;
    }
    // LB16
    if matches!(a, Cl | Cp) && b == Ns {
        return true;
    }
    // LB17
    if a == B2 && b == B2 {
        return true;
    }
    // LB19
    if a == Qu || b == Qu {
        return true;
    }
    // LB21
    if matches!(b, Ba | Hy | Ns) || a == Bb {
        return true;
    }
    // LB22
    if b == In {
        return true;
    }
    // LB23
    if (a == Al && b == Nu) || (a == Nu && b == Al) {
        return true;
    }
    // LB23a
    if (a == Pr && matches!(b, Id | Em)) || (matches!(a, Id | Em) && b == Po) {
        return true;
    }
    // LB24
    if (matches!(a, Pr | Po) && b == Al) || (a == Al && matches!(b, Pr | Po)) {
        return true;
    }
    // LB25
    let lb25 = matches!(
        (a, b),
        (Cl, Po)
            | (Cp, Po)
            | (Cl, Pr)
            | (Cp, Pr)
            | (Nu, Po)
            | (Nu, Pr)
            | (Po, Op)
            | (Po, Nu)
            | (Pr, Op)
            | (Pr, Nu)
            | (Hy, Nu)
            | (Is, Nu)
            | (Nu, Nu)
            | (Sy, Nu)
    );
    if lb25 {
        return true;
    }
    // LB28
    if a == Al && b == Al {
        return true;
    }
    // LB29
    if a == Is && b == Al {
        return true;
    }
    // LB30
    if matches!(a, Al | Nu) && b == Op {
        return true;
    }
    if a == Cp && matches!(b, Al | Nu) {
        return true;
    }
    false
}

/// Compute the byte indices (exclusive end positions) after which a line
/// break opportunity exists. The end of the text is not included.
pub fn break_opportunities(s: &str) -> Vec<usize> {
    use Lb::*;
    let chars: Vec<(usize, char)> = s.char_indices().collect();
    let mut result = Vec::new();
    if chars.is_empty() {
        return result;
    }
    // Resolve classes with LB9/LB10 (combining marks attach to the previous
    // character).
    let mut classes: Vec<Lb> = Vec::with_capacity(chars.len());
    for (i, &(_, c)) in chars.iter().enumerate() {
        let mut cls = lb_class(c);
        if matches!(cls, Cm | Zwj) {
            if i > 0 {
                let prev = classes[i - 1];
                if !matches!(prev, Bk | Cr | Lf | Sp | Zw) {
                    cls = prev;
                } else {
                    cls = Al;
                }
            } else {
                cls = Al;
            }
        }
        classes.push(cls);
    }

    // `before_spaces` tracks the class before a run of spaces.
    let mut i = 0;
    while i + 1 < chars.len() {
        let a = classes[i];
        let b = classes[i + 1];
        let idx = chars[i + 1].0;
        let brk;
        if matches!(a, Bk | Lf) || (a == Cr && b != Lf) {
            brk = true;
        } else if a == Cr && b == Lf {
            brk = false;
        } else if matches!(b, Bk | Cr | Lf) {
            brk = false;
        } else if b == Sp || b == Zw {
            brk = false;
        } else if a == Zwj {
            brk = false;
        } else if a == Sp || a == Zw {
            // find class before the spaces
            let mut j = i;
            while j > 0 && classes[j] == Sp {
                j -= 1;
            }
            let before = classes[j];
            if before == Zw {
                brk = true;
            } else if classes[j] == Sp {
                // only spaces from the start of text
                brk = !(matches!(b, Cl | Cp | Ex | Is | Sy | Wj));
                // LB7/13 already handled; start-of-text spaces then text:
            } else if matches!(b, Cl | Cp | Ex | Is | Sy | Wj) {
                brk = false;
            } else if before == Op {
                brk = false;
            } else if before == Qu && b == Op {
                brk = false;
            } else if matches!(before, Cl | Cp) && b == Ns {
                brk = false;
            } else if before == B2 && b == B2 {
                brk = false;
            } else {
                brk = true;
            }
        } else {
            brk = !pair_prohibited(a, b);
        }
        if brk {
            result.push(idx);
        }
        i += 1;
    }
    result
}

#[derive(Clone, Debug)]
struct Word<'a> {
    word: &'a str,
    whitespace: &'a str,
    penalty: &'a str,
    width: usize,
}

impl<'a> Word<'a> {
    fn from(s: &'a str) -> Word<'a> {
        let trimmed = s.trim_end_matches(' ');
        Word {
            word: trimmed,
            width: display_width(trimmed),
            whitespace: &s[trimmed.len()..],
            penalty: "",
        }
    }
    fn whitespace_width(&self) -> usize {
        self.whitespace.len()
    }
    fn penalty_width(&self) -> usize {
        display_width(self.penalty)
    }
}

fn find_words(line: &str) -> Vec<Word<'_>> {
    // Break opportunities, suppressing those right after '-' or soft hyphen.
    let stripped_ops: Vec<usize> = break_opportunities(line)
        .into_iter()
        .filter(|&idx| {
            let prev = line[..idx].chars().next_back();
            !matches!(prev, Some('-') | Some('\u{ad}'))
        })
        .collect();
    let mut words = Vec::new();
    let mut start = 0;
    for idx in stripped_ops {
        words.push(Word::from(&line[start..idx]));
        start = idx;
    }
    if start < line.len() {
        words.push(Word::from(&line[start..]));
    }
    words
}

fn split_points(word: &str) -> Vec<usize> {
    let mut splits = Vec::new();
    for (idx, _) in word.match_indices('-') {
        let prev = word[..idx].chars().next_back();
        let next = word[idx + 1..].chars().next();
        if prev.map(|c| c.is_alphanumeric()).unwrap_or(false)
            && next.map(|c| c.is_alphanumeric()).unwrap_or(false)
        {
            splits.push(idx + 1);
        }
    }
    splits
}

fn split_words<'a>(words: Vec<Word<'a>>) -> Vec<Word<'a>> {
    let mut out = Vec::new();
    for word in words {
        let mut prev = 0;
        let points = split_points(word.word);
        for idx in points {
            let need_hyphen = !word.word[..idx].ends_with('-');
            out.push(Word {
                word: &word.word[prev..idx],
                width: display_width(&word.word[prev..idx]),
                whitespace: "",
                penalty: if need_hyphen { "-" } else { "" },
            });
            prev = idx;
        }
        if prev < word.word.len() || prev == 0 {
            out.push(Word {
                word: &word.word[prev..],
                width: display_width(&word.word[prev..]),
                whitespace: word.whitespace,
                penalty: word.penalty,
            });
        }
    }
    out
}

fn break_apart<'a>(word: &Word<'a>, line_width: usize) -> Vec<Word<'a>> {
    let mut out = Vec::new();
    let mut start = 0;
    let mut width = 0;
    let s = word.word;
    let mut iter = s.char_indices().peekable();
    while let Some((idx, ch)) = iter.next() {
        if ch == '\u{1b}' {
            // skip ANSI escape
            if let Some(&(_, '[')) = iter.peek() {
                iter.next();
                for (_, c) in iter.by_ref() {
                    if ('\u{40}'..='\u{7e}').contains(&c) {
                        break;
                    }
                }
            }
            continue;
        }
        let w = ch_width(ch);
        if width > 0 && width + w > line_width {
            out.push(Word {
                word: &s[start..idx],
                width,
                whitespace: "",
                penalty: "",
            });
            start = idx;
            width = 0;
        }
        width += w;
    }
    if start < s.len() {
        out.push(Word {
            word: &s[start..],
            width,
            whitespace: word.whitespace,
            penalty: word.penalty,
        });
    }
    out
}

const NLINE_PENALTY: i64 = 1000;
const OVERFLOW_PENALTY: i64 = 50 * 50;
const SHORT_LAST_LINE_FRACTION: i64 = 4;
const SHORT_LAST_LINE_PENALTY: i64 = 25;
const HYPHEN_PENALTY: i64 = 25;

fn wrap_optimal_fit(fragments: &[Word<'_>], line_widths: &[usize]) -> Vec<(usize, usize)> {
    let n = fragments.len();
    let default_line_width = *line_widths.last().unwrap_or(&0) as i64;
    let mut widths: Vec<i64> = Vec::with_capacity(n + 1);
    let mut width = 0i64;
    widths.push(0);
    for f in fragments {
        width += (f.width + f.whitespace_width()) as i64;
        widths.push(width);
    }

    let mut line_numbers: Vec<usize> = vec![0];
    // minima[j] = (i, cost)
    let mut minima: Vec<(usize, i64)> = vec![(0, 0)];

    let cost = |minima: &Vec<(usize, i64)>, line_numbers: &mut Vec<usize>, i: usize, j: usize| -> i64 {
        // line number for fragment i
        while line_numbers.len() < i + 1 {
            let pos = line_numbers.len();
            let ln = 1 + line_numbers[minima[pos].0];
            line_numbers.push(ln);
        }
        let line_number = line_numbers[i];
        let line_width = line_widths
            .get(line_number)
            .map(|w| *w as i64)
            .unwrap_or(default_line_width);
        let target_width = std::cmp::max(1, line_width);
        let lw = widths[j] - widths[i] - fragments[j - 1].whitespace_width() as i64
            + fragments[j - 1].penalty_width() as i64;
        let mut c = minima[i].1 + NLINE_PENALTY;
        if lw > target_width {
            let overflow = lw - target_width;
            c += overflow * OVERFLOW_PENALTY;
        } else if j < n {
            let gap = target_width - lw;
            c += gap * gap;
        } else if i + 1 == j && lw < target_width / SHORT_LAST_LINE_FRACTION {
            c += SHORT_LAST_LINE_PENALTY;
        }
        if fragments[j - 1].penalty_width() > 0 {
            c += HYPHEN_PENALTY;
        }
        c
    };

    let size = n + 1;
    online_column_minima(size, &mut minima, &mut line_numbers, &cost);

    let mut lines = Vec::new();
    let mut pos = n;
    if n == 0 {
        return lines;
    }
    loop {
        let prev = minima[pos].0;
        lines.push((prev, pos));
        pos = prev;
        if pos == 0 {
            break;
        }
    }
    lines.reverse();
    lines
}

type CostFn<'a> = dyn Fn(&Vec<(usize, i64)>, &mut Vec<usize>, usize, usize) -> i64 + 'a;

/// Port of the online column minima algorithm (Galil & Park / SMAWK based).
fn online_column_minima(
    size: usize,
    result: &mut Vec<(usize, i64)>,
    line_numbers: &mut Vec<usize>,
    matrix: &CostFn<'_>,
) {
    if size == 0 {
        return;
    }
    let mut finished = 0usize;
    let mut base = 0usize;
    let mut tentative = 0usize;

    while finished < size - 1 {
        let i = finished + 1;
        if i > tentative {
            let rows: Vec<usize> = (base..finished + 1).collect();
            tentative = std::cmp::min(finished + rows.len(), size - 1);
            let cols: Vec<usize> = (finished + 1..tentative + 1).collect();
            let mut statuses: Vec<(usize, i64)> = Vec::with_capacity(cols.len());
            {
                let snapshot = &result[..finished + 1];
                let snap_vec: Vec<(usize, i64)> = snapshot.to_vec();
                let f = |r: usize, c: usize, ln: &mut Vec<usize>| -> i64 { matrix(&snap_vec, ln, r, c) };
                let minima_rows = smawk_column_minima(&rows, &cols, line_numbers, &f);
                for (idx, &col) in cols.iter().enumerate() {
                    let row = minima_rows[idx];
                    let v = f(row, col, line_numbers);
                    statuses.push((row, v));
                }
            }
            result.truncate(finished + 1);
            result.extend(statuses);
            finished = i;
            continue;
        }

        let snap: Vec<(usize, i64)> = result[..finished + 1].to_vec();
        let diag = matrix(&snap, line_numbers, i - 1, i);
        if diag < result[i].1 {
            result[i] = (i - 1, diag);
            base = i - 1;
            tentative = i;
            finished = i;
            result.truncate(finished + 1);
            continue;
        }

        if matrix(&snap, line_numbers, i - 1, tentative) >= result[tentative].1 {
            finished = i;
            continue;
        }

        base = i - 1;
        tentative = i;
        finished = i;
        result.truncate(finished + 1);
    }
}

/// SMAWK: compute for each column the row index of the minimum (leftmost
/// on ties in row order) of a totally monotone matrix.
fn smawk_column_minima(
    rows: &[usize],
    cols: &[usize],
    ln: &mut Vec<usize>,
    m: &dyn Fn(usize, usize, &mut Vec<usize>) -> i64,
) -> Vec<usize> {
    let mut minima = vec![0usize; cols.len()];
    smawk_inner(m, rows, cols, ln, &mut minima, 0, 1);
    minima
}

#[allow(clippy::too_many_arguments)]
fn smawk_inner(
    m: &dyn Fn(usize, usize, &mut Vec<usize>) -> i64,
    rows: &[usize],
    cols: &[usize],
    ln: &mut Vec<usize>,
    minima: &mut [usize],
    offset: usize,
    stride: usize,
) {
    // `cols` here is the full list; we operate on the subsequence
    // cols[offset], cols[offset + stride], ...
    let ncols = if offset >= cols.len() {
        0
    } else {
        (cols.len() - offset + stride - 1) / stride
    };
    if ncols == 0 {
        return;
    }
    let col_at = |k: usize| cols[offset + k * stride];

    // REDUCE
    let mut stack: Vec<usize> = Vec::with_capacity(ncols);
    for &r in rows {
        // TODO: use the actual row indices
        while !stack.is_empty() {
            let k = stack.len() - 1;
            let c = col_at(k);
            let top = *stack.last().unwrap();
            if m(top, c, ln) <= m(r, c, ln) {
                break;
            }
            stack.pop();
        }
        if stack.len() != ncols {
            stack.push(r);
        }
    }
    let rows2 = stack;

    // recurse on odd columns
    smawk_inner(m, &rows2, cols, ln, minima, offset + stride, stride * 2);

    // INTERPOLATE for even columns
    let mut r = 0usize;
    let mut k = 0usize;
    while k < ncols {
        let c = col_at(k);
        let last_row = if k + 1 < ncols {
            minima[offset + (k + 1) * stride]
        } else {
            *rows2.last().unwrap()
        };
        let mut pair = (rows2[r], m(rows2[r], c, ln));
        while rows2[r] != last_row {
            r += 1;
            let v = m(rows2[r], c, ln);
            if v < pair.1 {
                pair = (rows2[r], v);
            }
        }
        minima[offset + k * stride] = pair.0;
        k += 2;
    }
}

/// Wrap `text` like `textwrap::fill` with the given width and indents.
pub fn fill(text: &str, width: usize, initial_indent: &str, subsequent_indent: &str) -> String {
    wrap(text, width, initial_indent, subsequent_indent).join("\n")
}

pub fn wrap(text: &str, width: usize, initial_indent: &str, subsequent_indent: &str) -> Vec<String> {
    let initial_width = width.saturating_sub(display_width(initial_indent));
    let subsequent_width = width.saturating_sub(display_width(subsequent_indent));
    let mut lines: Vec<String> = Vec::new();
    for line in text.split('\n') {
        let words = find_words(line);
        let split = split_words(words);
        let mut broken: Vec<Word<'_>> = Vec::new();
        for w in split {
            if w.width > subsequent_width {
                broken.extend(break_apart(&w, subsequent_width));
            } else {
                broken.push(w);
            }
        }
        if !initial_indent.is_empty() {
            broken.insert(0, Word::from(""));
        }
        let line_widths = [initial_width, subsequent_width];
        let wrapped = wrap_optimal_fit(&broken, &line_widths);
        let mut idx = 0usize;
        if wrapped.is_empty() {
            // no fragments at all
            let mut result = String::new();
            if lines.is_empty() && !initial_indent.is_empty() {
                result.push_str(initial_indent);
            } else if !lines.is_empty() && !subsequent_indent.is_empty() {
                result.push_str(subsequent_indent);
            }
            lines.push(result);
            continue;
        }
        for (start, end) in wrapped {
            let words = &broken[start..end];
            let last = match words.last() {
                None => {
                    lines.push(String::new());
                    continue;
                }
                Some(w) => w,
            };
            let len: usize = words
                .iter()
                .map(|w| w.word.len() + w.whitespace.len())
                .sum::<usize>()
                - last.whitespace.len();
            let mut result = if lines.is_empty() && !initial_indent.is_empty() {
                initial_indent.to_string()
            } else if !lines.is_empty() && !subsequent_indent.is_empty() {
                subsequent_indent.to_string()
            } else {
                String::new()
            };
            result.push_str(&line[idx..idx + len]);
            if !last.penalty.is_empty() {
                result.push_str(last.penalty);
            }
            lines.push(result);
            idx += len + last.whitespace.len();
        }
    }
    lines
}
