//! Diagnostic reports, rendered in a "graphical" human format or as JSON.

use crate::textwrap;
use std::fmt::Write as _;
use unicode_width::UnicodeWidthChar;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Severity {
    Error,
    Warning,
    Advice,
}

#[derive(Clone, Debug)]
pub struct Label {
    pub text: Option<String>,
    pub offset: usize,
    pub len: usize,
}

#[derive(Clone, Debug)]
pub struct Source {
    pub name: String,
    pub contents: String,
}

/// An element of a diagnostic's cause chain.
#[derive(Clone, Debug)]
pub enum Cause {
    /// A plain error message.
    Msg(String),
    /// A nested diagnostic (rendered as a full report, minus its causes).
    Diag(Box<Diag>),
}

impl Cause {
    fn to_display(&self) -> String {
        match self {
            Cause::Msg(m) => m.clone(),
            Cause::Diag(d) => d.message.clone(),
        }
    }
}

#[derive(Clone, Debug)]
pub struct Diag {
    pub message: String,
    pub severity: Severity,
    pub help: Option<String>,
    pub source: Option<Source>,
    pub labels: Vec<Label>,
    pub related: Vec<Diag>,
    /// The flattened cause chain.
    pub causes: Vec<Cause>,
}

impl Diag {
    pub fn error(message: impl Into<String>) -> Self {
        Diag {
            message: message.into(),
            severity: Severity::Error,
            help: None,
            source: None,
            labels: vec![],
            related: vec![],
            causes: vec![],
        }
    }
    pub fn warning(message: impl Into<String>) -> Self {
        let mut d = Self::error(message);
        d.severity = Severity::Warning;
        d
    }
    pub fn with_help(mut self, help: impl Into<String>) -> Self {
        self.help = Some(help.into());
        self
    }
    pub fn with_cause(mut self, cause: impl Into<String>) -> Self {
        self.causes.push(Cause::Msg(cause.into()));
        self
    }
    pub fn with_causes(mut self, causes: Vec<String>) -> Self {
        for c in causes {
            self.causes.push(Cause::Msg(c));
        }
        self
    }
    /// Push a nested diagnostic (and its own chain) onto this cause chain.
    pub fn with_diag_cause(mut self, inner: Diag) -> Self {
        let mut inner = inner;
        let rest = std::mem::take(&mut inner.causes);
        self.causes.push(Cause::Diag(Box::new(inner)));
        self.causes.extend(rest);
        self
    }
}

pub struct Theme {
    pub unicode: bool,
    pub color: bool,
}

struct Chars {
    hbar: char,
    vbar: char,
    vbar_break: char,
    uarrow: char,
    rarrow: char,
    ltop: char,
    lbot: char,
    lcross: char,
    underbar: char,
    underline: char,
    error: &'static str,
    warning: &'static str,
    advice: &'static str,
}

const UNICODE_CHARS: Chars = Chars {
    hbar: '─',
    vbar: '│',
    vbar_break: '·',
    uarrow: '▲',
    rarrow: '▶',
    ltop: '╭',
    lbot: '╰',
    lcross: '├',
    underbar: '┬',
    underline: '─',
    error: "×",
    warning: "⚠",
    advice: "☞",
};

const ASCII_CHARS: Chars = Chars {
    hbar: '-',
    vbar: '|',
    vbar_break: ':',
    uarrow: '^',
    rarrow: '>',
    ltop: ',',
    lbot: '`',
    lcross: '|',
    underbar: '|',
    underline: '^',
    error: "x",
    warning: "!",
    advice: "i",
};

const TERM_WIDTH: usize = 120;
const CONTEXT_LINES: usize = 1;
const TAB_WIDTH: usize = 4;

pub struct Renderer {
    chars: &'static Chars,
    color: bool,
}

fn paint(color: bool, code: &str, s: &str) -> String {
    if color && !s.is_empty() {
        format!("\x1b[{code}m{s}\x1b[39m")
    } else {
        s.to_string()
    }
}

fn paint_effect(color: bool, effects: &str, fg: Option<&str>, s: &str) -> String {
    if !color {
        return s.to_string();
    }
    let mut out = String::new();
    out.push_str(&format!("\x1b[{effects}m"));
    if let Some(fg) = fg {
        out.push_str(&format!("\x1b[{fg}m"));
    }
    out.push_str(s);
    out.push_str("\x1b[0m\x1b[39m\x1b[49m");
    out
}

impl Renderer {
    pub fn new(theme: &Theme) -> Self {
        Renderer {
            chars: if theme.unicode {
                &UNICODE_CHARS
            } else {
                &ASCII_CHARS
            },
            color: theme.color,
        }
    }

    fn severity_style(&self, sev: Severity) -> &'static str {
        match sev {
            Severity::Error => "31",
            Severity::Warning => "33",
            Severity::Advice => "36",
        }
    }

    pub fn render(&self, diag: &Diag) -> String {
        let mut out = String::new();
        self.render_report(&mut out, diag, true);
        out
    }

    fn render_report(&self, f: &mut String, diag: &Diag, with_causes: bool) {
        self.render_causes(f, diag, with_causes);
        self.render_snippets(f, diag, diag.source.as_ref());
        self.render_footer(f, diag);
        self.render_related(f, diag, diag.source.as_ref());
    }

    fn render_causes(&self, f: &mut String, diag: &Diag, with_causes: bool) {
        let style = self.severity_style(diag.severity);
        let icon = match diag.severity {
            Severity::Error => self.chars.error,
            Severity::Warning => self.chars.warning,
            Severity::Advice => self.chars.advice,
        };
        let initial_indent = format!("  {} ", paint(self.color, style, icon));
        let rest_indent = format!("  {} ", paint(self.color, style, &self.chars.vbar.to_string()));
        let width = TERM_WIDTH.saturating_sub(2);
        let _ = writeln!(
            f,
            "{}",
            textwrap::fill(&diag.message, width, &initial_indent, &rest_indent)
        );
        if !with_causes {
            return;
        }
        let n = diag.causes.len();
        for (i, cause) in diag.causes.iter().enumerate() {
            let is_last = i + 1 == n;
            let ch = if !is_last {
                self.chars.lcross
            } else {
                self.chars.lbot
            };
            let initial = paint(
                self.color,
                style,
                &format!("  {}{}{} ", ch, self.chars.hbar, self.chars.rarrow),
            );
            let rest = paint(
                self.color,
                style,
                &format!("  {}   ", if is_last { ' ' } else { self.chars.vbar }),
            );
            match cause {
                Cause::Diag(d) => {
                    let mut inner = String::new();
                    self.render_report(&mut inner, d, false);
                    let _ = writeln!(f, "{}", textwrap::fill(&inner, width, &initial, &rest));
                }
                Cause::Msg(m) => {
                    let _ = writeln!(f, "{}", textwrap::fill(m, width, &initial, &rest));
                }
            }
        }
    }

    fn render_footer(&self, f: &mut String, diag: &Diag) {
        if let Some(help) = &diag.help {
            let width = TERM_WIDTH.saturating_sub(4);
            let initial = paint(self.color, "36", "  help: ");
            let _ = writeln!(f, "{}", textwrap::fill(help, width, &initial, "        "));
        }
    }

    fn render_related(&self, f: &mut String, diag: &Diag, parent_src: Option<&Source>) {
        if diag.related.is_empty() {
            return;
        }
        let _ = writeln!(f);
        for rel in &diag.related {
            match rel.severity {
                Severity::Error => f.push_str("Error: "),
                Severity::Warning => f.push_str("Warning: "),
                Severity::Advice => f.push_str("Advice: "),
            }
            self.render_causes(f, rel, true);
            let src = rel.source.as_ref().or(parent_src);
            self.render_snippets(f, rel, src);
            self.render_footer(f, rel);
            self.render_related(f, rel, src);
        }
    }

    fn render_snippets(&self, f: &mut String, diag: &Diag, source: Option<&Source>) {
        let source = match source {
            Some(s) => s,
            None => return,
        };
        if diag.labels.is_empty() {
            return;
        }
        let mut labels = diag.labels.clone();
        labels.sort_by_key(|l| l.offset);
        let mut contents = Vec::new();
        for label in &labels {
            match read_span(
                source.contents.as_bytes(),
                label.offset,
                label.len,
                CONTEXT_LINES,
                CONTEXT_LINES,
            ) {
                Some(c) => contents.push(c),
                None => return,
            }
        }
        let mut contexts: Vec<(Label, SpanContents)> = Vec::new();
        for (right, right_conts) in labels.iter().cloned().zip(contents.into_iter()) {
            if contexts.is_empty() {
                contexts.push((right, right_conts));
            } else {
                let (left, left_conts) = contexts.last().unwrap().clone();
                let left_end = left.offset + left.len;
                let right_end = right.offset + right.len;
                if left_conts.line + left_conts.line_count >= right_conts.line {
                    let new_span = Label {
                        text: left.text.clone(),
                        offset: left.offset,
                        len: if right_end >= left_end {
                            right_end - left.offset
                        } else {
                            left.len
                        },
                    };
                    if read_span(
                        source.contents.as_bytes(),
                        new_span.offset,
                        new_span.len,
                        CONTEXT_LINES,
                        CONTEXT_LINES,
                    )
                    .is_some()
                    {
                        contexts.pop();
                        contexts.push((new_span, left_conts));
                    } else {
                        contexts.push((right, right_conts));
                    }
                } else {
                    contexts.push((right, right_conts));
                }
            }
        }
        for (ctx, _) in contexts {
            self.render_context(f, source, &ctx, &labels);
        }
    }

    fn render_context(&self, f: &mut String, source: &Source, context: &Label, labels: &[Label]) {
        let (contents, lines) = match get_lines(source, context) {
            Some(x) => x,
            None => return,
        };
        let mut max_gutter = 0usize;
        for line in &lines {
            let mut num = 0;
            for hl in labels {
                if !line.span_line_only(hl) && line.span_applies(hl) {
                    num += 1;
                }
            }
            max_gutter = max_gutter.max(num);
        }
        let linum_width = lines
            .last()
            .map(|l| l.line_number)
            .unwrap_or(0)
            .to_string()
            .len();
        let _ = write!(
            f,
            "{}{}{}",
            " ".repeat(linum_width + 2),
            self.chars.ltop,
            self.chars.hbar
        );
        let name = paint_effect(self.color, "1;4", Some("36"), &source.name);
        let _ = writeln!(f, "[{}:{}:{}]", name, contents.line + 1, contents.column + 1);

        for line in &lines {
            self.write_linum(f, linum_width, line.line_number);
            self.render_line_gutter(f, max_gutter, line, labels);
            self.render_line_text(f, &line.text);
            let single_line: Vec<&Label> = labels
                .iter()
                .filter(|hl| line.span_applies(hl) && line.span_line_only(hl))
                .collect();
            if !single_line.is_empty() {
                self.write_no_linum(f, linum_width);
                self.render_highlight_gutter(f, max_gutter, line, labels);
                self.render_single_line_highlights(f, line, linum_width, max_gutter, &single_line, labels);
            }
            let multi: Vec<&Label> = labels
                .iter()
                .filter(|hl| line.span_applies(hl) && !line.span_line_only(hl))
                .collect();
            for hl in multi {
                if hl.text.is_some() && line.span_ends(hl) && !line.span_starts(hl) {
                    self.write_no_linum(f, linum_width);
                    self.render_highlight_gutter(f, max_gutter, line, labels);
                    let _ = writeln!(
                        f,
                        "{}{} {}",
                        self.chars.lbot,
                        self.chars.hbar,
                        hl.text.as_deref().unwrap_or("")
                    );
                }
            }
        }
        let _ = writeln!(
            f,
            "{}{}{}",
            " ".repeat(linum_width + 2),
            self.chars.lbot,
            self.chars.hbar.to_string().repeat(4)
        );
    }

    fn write_linum(&self, f: &mut String, width: usize, linum: usize) {
        let num = format!("{:>width$}", linum, width = width);
        let num = if self.color {
            format!("\x1b[2m{}\x1b[0m\x1b[39m\x1b[49m", linum)
                .replace(&linum.to_string(), &num)
        } else {
            num
        };
        let _ = write!(f, " {} {} ", num, self.chars.vbar);
    }

    fn write_no_linum(&self, f: &mut String, width: usize) {
        let _ = write!(f, " {:width$} {} ", "", self.chars.vbar_break, width = width);
    }

    fn render_line_gutter(&self, f: &mut String, max_gutter: usize, line: &Line, labels: &[Label]) {
        if max_gutter == 0 {
            return;
        }
        let chars = self.chars;
        let mut gutter = String::new();
        let applicable: Vec<&Label> = labels.iter().filter(|hl| line.span_applies(hl)).collect();
        let mut arrow = false;
        for (i, hl) in applicable.iter().enumerate() {
            if line.span_starts(hl) {
                gutter.push(chars.ltop);
                gutter.push_str(
                    &chars
                        .hbar
                        .to_string()
                        .repeat(max_gutter.saturating_sub(i)),
                );
                gutter.push(chars.rarrow);
                arrow = true;
                break;
            } else if line.span_ends(hl) {
                if hl.text.is_some() {
                    gutter.push(chars.lcross);
                } else {
                    gutter.push(chars.lbot);
                }
                gutter.push_str(
                    &chars
                        .hbar
                        .to_string()
                        .repeat(max_gutter.saturating_sub(i)),
                );
                gutter.push(chars.rarrow);
                arrow = true;
                break;
            } else if line.span_flyby(hl) {
                gutter.push(chars.vbar);
            } else {
                gutter.push(' ');
            }
        }
        let pad = max_gutter + 1 + if arrow { 0 } else { 1 };
        let _ = write!(f, "{:width$}", gutter, width = pad.max(gutter.chars().count()));
    }

    fn render_highlight_gutter(&self, f: &mut String, max_gutter: usize, line: &Line, labels: &[Label]) {
        if max_gutter == 0 {
            return;
        }
        let mut gutter = String::new();
        let applicable: Vec<&Label> = labels.iter().filter(|hl| line.span_applies(hl)).collect();
        for (i, hl) in applicable.iter().enumerate() {
            if !line.span_line_only(hl) && line.span_ends(hl) {
                gutter.push(self.chars.lbot);
                gutter.push_str(
                    &self
                        .chars
                        .hbar
                        .to_string()
                        .repeat(max_gutter.saturating_sub(i) + 2),
                );
                break;
            } else {
                gutter.push(self.chars.vbar);
            }
        }
        let _ = write!(f, "{:width$}", gutter, width = max_gutter + 1);
    }

    fn line_visual_char_width(&self, text: &str) -> Vec<usize> {
        let mut column = 0;
        text.chars()
            .map(|c| {
                let w = if c == '\t' {
                    TAB_WIDTH - column % TAB_WIDTH
                } else {
                    c.width().unwrap_or(0)
                };
                column += w;
                w
            })
            .collect()
    }

    fn visual_offset(&self, line: &Line, offset: usize) -> usize {
        let text_index = offset.saturating_sub(line.offset);
        let end = text_index.min(line.text.len());
        let mut end = end;
        while !line.text.is_char_boundary(end) {
            end -= 1;
        }
        let text = &line.text[..end];
        let w: usize = self.line_visual_char_width(text).iter().sum();
        if text_index > line.text.len() {
            w + 1
        } else {
            w
        }
    }

    fn render_line_text(&self, f: &mut String, text: &str) {
        let widths = self.line_visual_char_width(text);
        for (c, w) in text.chars().zip(widths) {
            if c == '\t' {
                for _ in 0..w {
                    f.push(' ');
                }
            } else {
                f.push(c);
            }
        }
        f.push('\n');
    }

    fn render_single_line_highlights(
        &self,
        f: &mut String,
        line: &Line,
        linum_width: usize,
        max_gutter: usize,
        single_liners: &[&Label],
        all: &[Label],
    ) {
        let mut underlines = String::new();
        let mut highest = 0;
        let chars = self.chars;
        let mut vbar_offsets: Vec<(&Label, usize)> = Vec::new();
        for (idx, hl) in single_liners.iter().enumerate() {
            let start = self.visual_offset(line, hl.offset).max(highest);
            let end = self.visual_offset(line, hl.offset + hl.len).max(start + 1);
            let vbar_offset = (start + end) / 2;
            let num_left = vbar_offset - start;
            let num_right = end - vbar_offset - 1;
            if start < end {
                let mid = if hl.len == 0 {
                    chars.uarrow
                } else if hl.text.is_some() {
                    chars.underbar
                } else {
                    chars.underline
                };
                let s = format!(
                    "{:width$}{}{}{}",
                    "",
                    chars.underline.to_string().repeat(num_left),
                    mid,
                    chars.underline.to_string().repeat(num_right),
                    width = start.saturating_sub(highest)
                );
                let color = ["35", "33", "32"][idx % 3];
                underlines.push_str(&paint_effect(self.color, "1", Some(color), &s));
            }
            highest = highest.max(end);
            vbar_offsets.push((hl, vbar_offset));
        }
        let _ = writeln!(f, "{}", underlines);

        for (ri, hl) in single_liners.iter().enumerate().rev() {
            if let Some(label) = &hl.text {
                self.write_no_linum(f, linum_width);
                self.render_highlight_gutter(f, max_gutter, line, all);
                let mut curr_offset = 1usize;
                for (oi, (offset_hl, vbar_offset)) in vbar_offsets.iter().enumerate() {
                    while curr_offset < *vbar_offset + 1 {
                        f.push(' ');
                        curr_offset += 1;
                    }
                    if oi != ri {
                        let _ = offset_hl;
                        f.push(chars.vbar);
                        curr_offset += 1;
                    } else {
                        let _ = writeln!(
                            f,
                            "{}{} {}",
                            chars.lbot,
                            chars.hbar.to_string().repeat(2),
                            label
                        );
                        break;
                    }
                }
            }
        }
    }
}

#[derive(Clone, Debug)]
struct SpanContents {
    offset: usize,
    len: usize,
    line: usize,
    column: usize,
    line_count: usize,
}

/// Port of the context-gathering algorithm used for snippets.
fn read_span(
    input: &[u8],
    span_offset: usize,
    span_len: usize,
    before: usize,
    after: usize,
) -> Option<SpanContents> {
    use std::collections::VecDeque;
    let mut offset = 0usize;
    let mut line_count = 0usize;
    let mut start_line = 0usize;
    let mut start_column = 0usize;
    let mut before_lines_starts: VecDeque<usize> = VecDeque::new();
    let mut current_line_start = 0usize;
    let mut end_lines = 0usize;
    let mut post_span = false;
    let mut post_span_got_newline = false;
    let mut i = 0usize;
    while i < input.len() {
        let ch = input[i];
        i += 1;
        if ch == b'\r' || ch == b'\n' {
            line_count += 1;
            if ch == b'\r' && i < input.len() && input[i] == b'\n' {
                i += 1;
                offset += 1;
            }
            if offset < span_offset {
                start_column = 0;
                before_lines_starts.push_back(current_line_start);
                if before_lines_starts.len() > before {
                    start_line += 1;
                    before_lines_starts.pop_front();
                }
            } else if offset >= span_offset + span_len.saturating_sub(1) && post_span {
                start_column = 0;
                if post_span_got_newline {
                    end_lines += 1;
                } else {
                    post_span_got_newline = true;
                }
                if end_lines >= after {
                    offset += 1;
                    break;
                }
            }
            current_line_start = offset + 1;
        } else if offset < span_offset {
            start_column += 1;
        }

        if offset >= (span_offset + span_len).saturating_sub(1) {
            post_span = true;
            if end_lines >= after {
                offset += 1;
                break;
            }
        }
        offset += 1;
    }

    if offset >= (span_offset + span_len).saturating_sub(1) {
        let starting_offset = before_lines_starts.front().copied().unwrap_or(if before == 0 {
            span_offset
        } else {
            0
        });
        Some(SpanContents {
            offset: starting_offset,
            len: offset - starting_offset,
            line: start_line,
            column: if before == 0 { start_column } else { 0 },
            line_count,
        })
    } else {
        None
    }
}

#[derive(Debug)]
struct Line {
    line_number: usize,
    offset: usize,
    length: usize,
    text: String,
}

impl Line {
    fn span_line_only(&self, span: &Label) -> bool {
        span.offset >= self.offset && span.offset + span.len <= self.offset + self.length
    }
    fn span_applies(&self, span: &Label) -> bool {
        let spanlen = if span.len == 0 { 1 } else { span.len };
        (span.offset >= self.offset && span.offset < self.offset + self.length)
            || (span.offset < self.offset && span.offset + spanlen > self.offset + self.length)
            || (span.offset + spanlen > self.offset
                && span.offset + spanlen <= self.offset + self.length)
    }
    fn span_flyby(&self, span: &Label) -> bool {
        span.offset < self.offset && span.offset + span.len > self.offset + self.length
    }
    fn span_starts(&self, span: &Label) -> bool {
        span.offset >= self.offset
    }
    fn span_ends(&self, span: &Label) -> bool {
        span.offset + span.len >= self.offset && span.offset + span.len <= self.offset + self.length
    }
}

fn get_lines(source: &Source, context: &Label) -> Option<(SpanContents, Vec<Line>)> {
    let contents = read_span(
        source.contents.as_bytes(),
        context.offset,
        context.len,
        CONTEXT_LINES,
        CONTEXT_LINES,
    )?;
    let data = &source.contents.as_bytes()[contents.offset..contents.offset + contents.len];
    let context_str = String::from_utf8_lossy(data).to_string();
    let mut line = contents.line;
    let mut column;
    let mut offset = contents.offset;
    let mut line_offset = offset;
    let mut iter = context_str.chars().peekable();
    let mut line_str = String::new();
    let mut lines = Vec::new();
    while let Some(ch) = iter.next() {
        offset += ch.len_utf8();
        let mut at_end_of_file = false;
        match ch {
            '\r' => {
                if iter.peek() == Some(&'\n') {
                    iter.next();
                    offset += 1;
                    line += 1;
                    column = 0;
                } else {
                    line_str.push(ch);
                    column = 1;
                }
                at_end_of_file = iter.peek().is_none();
            }
            '\n' => {
                at_end_of_file = iter.peek().is_none();
                line += 1;
                column = 0;
            }
            _ => {
                line_str.push(ch);
                column = 1;
            }
        }
        if iter.peek().is_none() && !at_end_of_file {
            line += 1;
        }
        if column == 0 || iter.peek().is_none() {
            lines.push(Line {
                line_number: line,
                offset: line_offset,
                length: offset - line_offset,
                text: line_str.clone(),
            });
            line_str.clear();
            line_offset = offset;
        }
    }
    Some((contents, lines))
}

fn json_escape(input: &str) -> String {
    let mut out = String::new();
    for c in input.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\r' => out.push_str("\\r"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c => out.push(c),
        }
    }
    out
}

/// Render a diagnostic as JSON.
pub fn render_json(diag: &Diag) -> String {
    let mut f = String::new();
    render_json_inner(&mut f, diag, None);
    f
}

fn render_json_inner(f: &mut String, diag: &Diag, parent_src: Option<&Source>) {
    let _ = write!(f, r#"{{"message": "{}","#, json_escape(&diag.message));
    let severity = match diag.severity {
        Severity::Error => "error",
        Severity::Warning => "warning",
        Severity::Advice => "advice",
    };
    let _ = write!(f, r#""severity": "{}","#, severity);
    f.push_str(r#""causes": ["#);
    let mut first = true;
    for c in &diag.causes {
        if !first {
            f.push(',');
        }
        first = false;
        let _ = write!(f, r#""{}""#, json_escape(&c.to_display()));
    }
    f.push_str("],");
    if let Some(help) = &diag.help {
        let _ = write!(f, r#""help": "{}","#, json_escape(help));
    }
    let src = diag.source.as_ref().or(parent_src);
    if let Some(src) = src {
        let mut filename = String::new();
        if let Some(label) = diag.labels.first() {
            if read_span(src.contents.as_bytes(), label.offset, label.len, 0, 0).is_some() {
                filename = src.name.clone();
            }
        }
        let _ = write!(f, r#""filename": "{}","#, json_escape(&filename));
    }
    f.push_str(r#""labels": ["#);
    let mut first = true;
    for label in &diag.labels {
        if !first {
            f.push(',');
        }
        first = false;
        f.push('{');
        if let Some(text) = &label.text {
            let _ = write!(f, r#""label": "{}","#, json_escape(text));
        }
        let _ = write!(
            f,
            r#""span": {{"offset": {},"length": {}}}}}"#,
            label.offset, label.len
        );
    }
    f.push_str("],");
    f.push_str(r#""related": ["#);
    let mut first = true;
    for rel in &diag.related {
        if !first {
            f.push(',');
        }
        first = false;
        render_json_inner(f, rel, src);
    }
    f.push(']');
    f.push('}');
}
