fn set<T: Clone>(dst: &mut T, src: &Option<T>) {
    if let Some(v) = src {
        *dst = v.clone();
    }
}

fn set_opt<T: Clone>(dst: &mut Option<T>, src: &Option<T>) {
    if let Some(v) = src {
        *dst = Some(v.clone());
    }
}

impl Config {
    pub fn apply_project(&mut self, p: &ProjectLayer) {
        set_opt(&mut self.project.name, &p.name);
        set_opt(&mut self.project.version, &p.version);
        set_opt(&mut self.project.description, &p.description);
        set_opt(&mut self.project.homepage, &p.homepage);
        set_opt(&mut self.project.repository, &p.repository);
        set_opt(&mut self.project.readme_path, &p.readme_path);
        set_opt(&mut self.project.license, &p.license);
    }

    pub fn apply_layer(&mut self, layer: &OrandaLayer) {
        if let Some(p) = &layer.project {
            self.apply_project(p);
        }
        if let Some(b) = &layer.build {
            set(&mut self.build.dist_dir, &b.dist_dir);
            set(&mut self.build.static_dir, &b.static_dir);
            set_opt(&mut self.build.path_prefix, &b.path_prefix);
            set(&mut self.build.additional_pages, &b.additional_pages);
        }
        if let Some(m) = &layer.marketing {
            self.marketing = Some(m.clone());
        }
        if let Some(s) = &layer.styles {
            set_opt(&mut self.styles.theme, &s.theme);
            if let Some(css) = &s.additional_css {
                self.styles.additional_css.extend(css.iter().cloned());
            }
            set(&mut self.styles.oranda_css_version, &s.oranda_css_version);
            set_opt(&mut self.styles.logo, &s.logo);
            set_opt(&mut self.styles.favicon, &s.favicon);
        }
        if let Some(c) = &layer.components {
            if let Some(cl) = &c.changelog {
                match cl {
                    BoolOr::Bool(false) => self.components.changelog = None,
                    BoolOr::Bool(true) => {
                        if self.components.changelog.is_none() {
                            self.components.changelog = Some(ChangelogConfig {
                                read_changelog_file: true,
                                rss_feed: true,
                            });
                        }
                    }
                    BoolOr::Val(v) => {
                        let mut cfg = self.components.changelog.clone().unwrap_or(ChangelogConfig {
                            read_changelog_file: true,
                            rss_feed: true,
                        });
                        set(&mut cfg.read_changelog_file, &v.read_changelog_file);
                        set(&mut cfg.rss_feed, &v.rss_feed);
                        self.components.changelog = Some(cfg);
                    }
                }
            }
            if let Some(mb) = &c.mdbook {
                match mb {
                    BoolOr::Bool(false) => self.components.mdbook = None,
                    BoolOr::Bool(true) => {
                        if self.components.mdbook.is_none() {
                            self.components.mdbook = Some(MdBookConfig {
                                path: None,
                                theme: true,
                            });
                        }
                    }
                    BoolOr::Val(v) => {
                        let mut cfg = self.components.mdbook.clone().unwrap_or(MdBookConfig {
                            path: None,
                            theme: true,
                        });
                        set_opt(&mut cfg.path, &v.path);
                        set(&mut cfg.theme, &v.theme);
                        self.components.mdbook = Some(cfg);
                    }
                }
            }
            if let Some(fu) = &c.funding {
                match fu {
                    BoolOr::Bool(false) => self.components.funding = None,
                    BoolOr::Bool(true) => {
                        if self.components.funding.is_none() {
                            self.components.funding = Some(FundingConfig::default());
                        }
                    }
                    BoolOr::Val(v) => {
                        let mut cfg = self.components.funding.clone().unwrap_or_default();
                        set_opt(&mut cfg.preferred_funding, &v.preferred_funding);
                        set_opt(&mut cfg.yml_path, &v.yml_path);
                        set_opt(&mut cfg.md_path, &v.md_path);
                        self.components.funding = Some(cfg);
                    }
                }
            }
            if let Some(ar) = &c.artifacts {
                match ar {
                    BoolOr::Bool(false) => self.components.artifacts = None,
                    BoolOr::Bool(true) => {
                        if self.components.artifacts.is_none() {
                            self.components.artifacts = Some(ArtifactsConfig::default());
                        }
                    }
                    BoolOr::Val(v) => {
                        let mut cfg = self.components.artifacts.clone().unwrap_or_default();
                        set(&mut cfg.auto, &v.auto);
                        set(&mut cfg.cargo_dist, &v.cargo_dist);
                        if let Some(pm) = &v.package_managers {
                            if let Some(p) = &pm.preferred {
                                for (k, val) in p {
                                    cfg.package_managers.preferred.insert(k.clone(), val.clone());
                                }
                            }
                            if let Some(a) = &pm.additional {
                                for (k, val) in a {
                                    cfg.package_managers.additional.insert(k.clone(), val.clone());
                                }
                            }
                        }
                        if let Some(h) = &v.hidden {
                            cfg.hidden.extend(h.iter().cloned());
                        }
                        set(&mut cfg.match_package_names, &v.match_package_names);
                        self.components.artifacts = Some(cfg);
                    }
                }
            }
            set_opt(&mut self.components.source, &c.source);
        }
    }
}

impl WorkspaceConfig {
    pub fn from_layer(layer: Option<&WorkspaceLayer>) -> Self {
        let mut ws = WorkspaceConfig {
            generate_index: true,
            ..Default::default()
        };
        if let Some(l) = layer {
            set_opt(&mut ws.name, &l.name);
            set(&mut ws.generate_index, &l.generate_index);
            set(&mut ws.members, &l.members);
            set(&mut ws.preferred_members, &l.preferred_members);
            set(&mut ws.auto, &l.auto);
            set_opt(&mut ws.docs_path, &l.docs_path);
        }
        ws
    }
}
