//! Status messages printed to stdout.

use std::io::IsTerminal;
use std::sync::atomic::{AtomicBool, Ordering};

static VERBOSE: AtomicBool = AtomicBool::new(false);

pub fn set_verbose(v: bool) {
    VERBOSE.store(v, Ordering::SeqCst);
}

pub fn verbose() -> bool {
    VERBOSE.load(Ordering::SeqCst)
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Info,
    Success,
    Warning,
    Debug,
    Error,
}

pub fn stdout_color() -> bool {
    if std::env::var_os("NO_COLOR").is_some() {
        return false;
    }
    if std::env::var_os("FORCE_COLOR").is_some() {
        return true;
    }
    match std::env::var("TERM") {
        Ok(t) if t != "dumb" => std::io::stdout().is_terminal(),
        _ => false,
    }
}

fn style(color: bool, fg: &str, s: &str) -> String {
    if color {
        format!("\x1b[1m\x1b[{fg}m{s}\x1b[0m\x1b[39m\x1b[49m")
    } else {
        s.to_string()
    }
}

pub fn format(kind: Kind, text: &str, prefix: Option<&str>, color: bool) -> String {
    let (icon, label, icon_fg, text_fg) = match kind {
        Kind::Info => ("\u{21aa}", "INFO", "37", "37"),
        Kind::Success => ("\u{2713}", "SUCCESS", "32", "32"),
        Kind::Warning => ("\u{26a0}", "WARNING", "33", "33"),
        Kind::Debug => ("\u{21aa}", "DEBUG", "37", "35"),
        Kind::Error => ("\u{2717}", "ERROR", "31", "31"),
    };
    let mut out = String::new();
    if let Some(p) = prefix {
        out.push_str(&format!("{:>15} ", p));
    }
    out.push_str(&style(color, icon_fg, icon));
    out.push_str(&format!(" >o_o< {label}: "));
    out.push_str(&style(color, text_fg, text));
    out
}

pub fn print(kind: Kind, text: &str, prefix: Option<&str>) {
    if kind == Kind::Debug && !verbose() {
        return;
    }
    let s = format(kind, text, prefix, stdout_color());
    println!("{s}");
}

pub fn info(text: &str) {
    print(Kind::Info, text, None);
}

pub fn success(text: &str) {
    print(Kind::Success, text, None);
}

pub fn warning(text: &str, prefix: Option<&str>) {
    print(Kind::Warning, text, prefix);
}

pub fn debug(text: &str, prefix: Option<&str>) {
    print(Kind::Debug, text, prefix);
}
