//! Network access. Requests are resolved via the system resolver; this tool
//! does not ship an HTTPS client, so every request ends in a connection
//! error that mirrors what an offline environment reports.

use std::net::ToSocketAddrs;

#[derive(Debug, Clone)]
pub struct NetError {
    /// Display of the top-level error followed by each of its sources.
    pub chain: Vec<String>,
}

impl NetError {
    pub fn message(&self) -> String {
        self.chain.first().cloned().unwrap_or_default()
    }
    pub fn causes(&self) -> Vec<String> {
        self.chain.iter().skip(1).cloned().collect()
    }
}

const DEFAULT_DNS_ERROR: &str =
    "failed to lookup address information: Temporary failure in name resolution";

/// Normalize a URL the way a URL parser would serialize it.
pub fn normalize_url(raw: &str) -> String {
    match url::Url::parse(raw) {
        Ok(u) => u.to_string(),
        Err(_) => raw.to_string(),
    }
}

fn resolve_error(host: &str, port: u16) -> String {
    match (host, port).to_socket_addrs() {
        Ok(_) => DEFAULT_DNS_ERROR.to_string(),
        Err(e) => {
            let s = e.to_string();
            if s.starts_with("failed to lookup address information") {
                s
            } else {
                DEFAULT_DNS_ERROR.to_string()
            }
        }
    }
}

/// Attempt an HTTP GET. Returns the body on success.
pub fn get(raw_url: &str) -> Result<Vec<u8>, NetError> {
    let url = normalize_url(raw_url);
    let (host, port) = match url::Url::parse(&url) {
        Ok(u) => (
            u.host_str().unwrap_or("").to_string(),
            u.port_or_known_default().unwrap_or(443),
        ),
        Err(_) => (String::new(), 443),
    };
    let dns = resolve_error(&host, port);
    let connect = format!("error trying to connect: dns error: {dns}");
    Err(NetError {
        chain: vec![
            format!("error sending request for url ({url}): {connect}"),
            connect,
            format!("dns error: {dns}"),
            dns,
        ],
    })
}

/// Fetch through the axo proxy first, falling back to GitHub directly.
pub fn get_with_proxy_fallback(proxy_url: &str, github_url: &str) -> Result<Vec<u8>, NetError> {
    match get(proxy_url) {
        Ok(b) => Ok(b),
        Err(e) => {
            println!(
                "Fetching from proxy encountered an error:\n {}.\n Falling back to GitHub directly...",
                e.message()
            );
            get(github_url)
        }
    }
}
