fn detect_js(package_json: &Path) -> Result<ProjectInfo, Diag> {
    let abs = abs_path(package_json);
    let name = abs.display().to_string();
    let contents = match std::fs::read_to_string(package_json) {
        Ok(c) => c,
        Err(e) => {
            return Err(Diag::error(format!(
                "failed to read asset from {}",
                package_json.display()
            ))
            .with_cause(e.to_string()))
        }
    };
    let manifest: Manifest = match serde_json::from_str(&contents) {
        Ok(m) => m,
        Err(e) => return Err(json_error_diag(&name, &contents, &e)),
    };
    let pkg_name = match manifest.name {
        Some(n) => n,
        None => {
            return Err(Diag::error(format!(
                "your package doesn't have a name: {name}"
            ))
            .with_help("is it a workspace? We don't support that yet."))
        }
    };
    let repository = match manifest.repository {
        Some(Repository::Str(s)) => Some(s),
        Some(Repository::Obj { url, .. }) => url,
        None => None,
    };
    Ok(ProjectInfo {
        layer: Some(ProjectLayer {
            name: Some(pkg_name),
            version: manifest.version.map(|v| v.0),
            description: manifest.description,
            homepage: manifest.homepage,
            repository,
            readme_path: None,
            license: manifest.license,
        }),
        cargo_dist: false,
        members: vec![],
    })
}
