fn detect_rust(root: &Path, cargo_toml: &Path) -> Result<ProjectInfo, Diag> {
    let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".to_string());
    let mut cmd = std::process::Command::new(cargo);
    cmd.args(["metadata", "--format-version", "1", "--no-deps", "--all-features"]);
    if !root.as_os_str().is_empty() && root != Path::new(".") {
        cmd.current_dir(root);
    }
    cmd.stdin(std::process::Stdio::null());
    let output = match cmd.output() {
        Ok(o) => o,
        Err(e) => {
            return Err(Diag::error("`cargo metadata` execution failed")
                .with_cause(format!("failed to start `cargo metadata`: {e}"))
                .with_cause(e.to_string()));
        }
    };
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
        return Err(Diag::error("`cargo metadata` execution failed")
            .with_cause(format!("`cargo metadata` exited with an error: {stderr}")));
    }
    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    // cargo may print other lines; find the JSON line
    let json_line = stdout
        .lines()
        .find(|l| l.starts_with('{'))
        .unwrap_or("")
        .to_string();
    let value: serde_json::Value = match serde_json::from_str(&json_line) {
        Ok(v) => v,
        Err(e) => {
            return Err(Diag::error("`cargo metadata` execution failed")
                .with_cause(format!("failed to parse `cargo metadata` output: {e}")))
        }
    };
    let mut info = ProjectInfo::default();
    let abs_manifest = abs_path(cargo_toml);
    let abs_manifest_canon = std::fs::canonicalize(cargo_toml).unwrap_or(abs_manifest.clone());
    if let Some(meta) = value.get("metadata") {
        if meta.get("dist").is_some() {
            info.cargo_dist = true;
        }
    }
    let workspace_root = value
        .get("workspace_root")
        .and_then(|v| v.as_str())
        .map(PathBuf::from);
    let members: Vec<String> = value
        .get("workspace_members")
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|x| x.as_str().map(|s| s.to_string()))
                .collect()
        })
        .unwrap_or_default();
    if let Some(pkgs) = value.get("packages").and_then(|v| v.as_array()) {
        for pkg in pkgs {
            let manifest_path = pkg
                .get("manifest_path")
                .and_then(|v| v.as_str())
                .map(PathBuf::from)
                .unwrap_or_default();
            let id = pkg.get("id").and_then(|v| v.as_str()).unwrap_or("");
            let is_member = members.iter().any(|m| m == id);
            if !is_member {
                continue;
            }
            if manifest_path == abs_manifest || manifest_path == abs_manifest_canon {
                let s = |k: &str| pkg.get(k).and_then(|v| v.as_str()).map(|s| s.to_string());
                info.layer = Some(ProjectLayer {
                    name: s("name"),
                    version: s("version"),
                    description: s("description"),
                    homepage: s("homepage"),
                    repository: s("repository"),
                    readme_path: s("readme").map(|r| {
                        let p = PathBuf::from(&r);
                        let dir = manifest_path.parent().map(|d| d.to_path_buf()).unwrap_or_default();
                        dir.join(p).display().to_string()
                    }),
                    license: s("license"),
                });
            } else if let (Some(name), Some(dir)) = (
                pkg.get("name").and_then(|v| v.as_str()),
                manifest_path.parent(),
            ) {
                let rel = match &workspace_root {
                    Some(wr) => dir.strip_prefix(wr).map(|p| p.to_path_buf()).unwrap_or(dir.to_path_buf()),
                    None => dir.to_path_buf(),
                };
                info.members.push(WorkspaceMember {
                    slug: name.to_string(),
                    path: rel.display().to_string(),
                });
            }
        }
    }
    Ok(info)
}

