struct NodeVersion(#[allow(dead_code)] String);

impl<'de> Deserialize<'de> for NodeVersion {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        struct V;
        impl<'de> serde::de::Visitor<'de> for V {
            type Value = NodeVersion;
            fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
                f.write_str("a version string")
            }
            fn visit_str<E: serde::de::Error>(self, v: &str) -> Result<NodeVersion, E> {
                parse_node_version(v).map_err(E::custom)?;
                Ok(NodeVersion(v.to_string()))
            }
        }
        d.deserialize_str(V)
    }
}

fn parse_node_version(v: &str) -> Result<(), &'static str> {
    let s = v.trim_start();
    let s = s.strip_prefix('v').or_else(|| s.strip_prefix('=')).unwrap_or(s);
    let s = s.trim_start();
    let bytes = s.as_bytes();
    let mut i = 0;
    for part in 0..3 {
        let start = i;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
        if i == start {
            return Err("Failed to parse version.");
        }
        if part < 2 {
            if i < bytes.len() && bytes[i] == b'.' {
                i += 1;
            } else {
                return Err("Failed to parse version.");
            }
        }
    }
    if i < bytes.len() && bytes[i] == b'-' {
        i += 1;
        let start = i;
        while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'.' || bytes[i] == b'-') {
            i += 1;
        }
        if i == start {
            return Err("Failed to parse version.");
        }
    }
    if i < bytes.len() && bytes[i] == b'+' {
        i += 1;
        let start = i;
        while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'.' || bytes[i] == b'-') {
            i += 1;
        }
        if i == start {
            return Err("Failed to parse version.");
        }
    }
    if i < bytes.len() {
        return Err("An unspecified error occurred.");
    }
    Ok(())
}

