/// Link generation for files at the root of the site, honoring the path
/// prefix.
pub fn link(path_prefix: Option<&str>, file: &str) -> String {
    match path_prefix {
        None => format!("/{file}"),
        Some(prefix) => {
            use std::path::{Component, Path};
            let mut parts: Vec<String> = Vec::new();
            if prefix.is_empty() {
                parts.push(encode("/"));
            }
            for c in Path::new(prefix).components() {
                let s = match c {
                    Component::RootDir => "/".to_string(),
                    Component::CurDir => ".".to_string(),
                    Component::ParentDir => "..".to_string(),
                    Component::Normal(n) => n.to_string_lossy().to_string(),
                    Component::Prefix(p) => p.as_os_str().to_string_lossy().to_string(),
                };
                parts.push(encode(&s));
            }
            let mut out = String::from("/");
            for p in parts {
                out.push_str(&p);
                out.push('/');
            }
            out.push_str(file);
            out
        }
    }
}

fn encode(s: &str) -> String {
    url::form_urlencoded::byte_serialize(s.as_bytes()).collect()
}

/// Build the artifacts JSON for a synthetic "current" release made purely
/// from configured package managers.
pub fn current_release_json(cfg: &ArtifactsConfig, path_prefix: Option<&str>) -> String {
    let mut installers: Vec<Value> = Vec::new();
    let mut labels: Vec<String> = Vec::new();
    let mut preferred_idx: Vec<usize> = Vec::new();
    for (label, hint) in &cfg.package_managers.preferred {
        let idx = installers.len();
        installers.push(installer(label, hint));
        labels.push(label.clone());
        if !cfg.hidden.iter().any(|h| h == label) {
            preferred_idx.push(idx);
        }
    }
    for (label, hint) in &cfg.package_managers.additional {
        installers.push(installer(label, hint));
        labels.push(label.clone());
    }
    let mut sorted = preferred_idx.clone();
    sorted.sort_by(|a, b| labels[*a].cmp(&labels[*b]));

    let mut targets = Map::new();
    let mut platforms: Vec<Value> = Vec::new();
    if !sorted.is_empty() {
        for t in ALL_TARGETS {
            targets.insert(t.to_string(), json!(sorted));
        }
        for (t, name) in PLATFORMS {
            platforms.push(json!({
                "target": [t],
                "display_name": name,
                "installers": sorted,
            }));
        }
    }

    let value = json!({
        "format_version": env!("CARGO_PKG_VERSION"),
        "tag": "current",
        "formatted_date": null,
        "platforms_with_downloads": platforms,
        "downloadable_files": [],
        "release": {
            "artifacts": {
                "files": [],
                "installers": installers,
                "targets": Value::Object(targets),
            }
        },
        "os_script": link(path_prefix, "artifacts.js"),
        "has_checksum_files": false,
    });
    serde_json::to_string(&value).unwrap_or_default()
}

fn installer(label: &str, hint: &str) -> Value {
    json!({
        "label": label,
        "description": "",
        "app_name": null,
        "method": {
            "type": "Run",
            "file": null,
            "run_hint": hint,
        }
    })
}
