mod build;
mod cli;
mod config;
mod css;
mod dev;
mod generate;
mod msg;
mod net;
mod project;
mod prompt;
mod report;
mod repo;
mod schema;
mod serve;
mod textwrap;

use report::{Diag, Renderer, Theme};
use std::io::IsTerminal;
use std::sync::atomic::{AtomicBool, Ordering};

static JSON_OUTPUT: AtomicBool = AtomicBool::new(false);

fn stderr_theme() -> Theme {
    let is_tty = std::io::stderr().is_terminal();
    let unicode = if !is_tty {
        true
    } else {
        let term = std::env::var("TERM").unwrap_or_default();
        if term == "linux" {
            false
        } else {
            let ctype = std::env::var("LC_ALL")
                .ok()
                .filter(|s| !s.is_empty())
                .or_else(|| std::env::var("LC_CTYPE").ok().filter(|s| !s.is_empty()))
                .or_else(|| std::env::var("LANG").ok().filter(|s| !s.is_empty()))
                .unwrap_or_default()
                .to_uppercase();
            ctype.ends_with("UTF8") || ctype.ends_with("UTF-8")
        }
    };
    let color = is_tty
        && std::env::var_os("NO_COLOR").is_none()
        && match std::env::var("TERM") {
            Ok(t) => t != "dumb",
            Err(_) => false,
        };
    Theme { unicode, color }
}

/// Print a (non-fatal) diagnostic to stderr.
pub fn print_diag(d: &Diag) {
    let r = Renderer::new(&stderr_theme());
    eprintln!("{}", r.render(d));
}

/// Report a fatal error and exit.
pub fn fatal(d: &Diag) -> ! {
    if JSON_OUTPUT.load(Ordering::SeqCst) {
        println!("{{\"diagnostic\": {}}}", report::render_json(d));
    }
    print_diag(d);
    std::process::exit(255);
}

fn install_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        let payload = if let Some(s) = info.payload().downcast_ref::<&str>() {
            s.to_string()
        } else if let Some(s) = info.payload().downcast_ref::<String>() {
            s.clone()
        } else {
            "Box<dyn Any>".to_string()
        };
        let mut d = Diag::error("oranda panicked.");
        if let Some(loc) = PANIC_LOCATION.with(|l| l.borrow().clone()) {
            d = d.with_cause(format!("at {loc}"));
        } else if let Some(loc) = info.location() {
            d = d.with_cause(format!("at {}:{}:{}", loc.file(), loc.line(), loc.column()));
        }
        d = d.with_cause(payload);
        d = d.with_help("set the `RUST_BACKTRACE=1` environment variable to display a backtrace.");
        if JSON_OUTPUT.load(Ordering::SeqCst) {
            println!("{{\"diagnostic\": {}}}", report::render_json(&d));
        }
        print_diag(&d);
        std::process::exit(255);
    }));
}

thread_local! {
    pub static PANIC_LOCATION: std::cell::RefCell<Option<String>> = const { std::cell::RefCell::new(None) };
}

/// Panic with a message, reporting the given source location.
pub fn panic_at(location: &str, message: String) -> ! {
    PANIC_LOCATION.with(|l| *l.borrow_mut() = Some(location.to_string()));
    std::panic::panic_any(message)
}

fn main() {
    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let bin_name = args
        .first()
        .and_then(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|s| s.to_string_lossy().to_string())
        })
        .unwrap_or_else(|| "oranda".to_string());
    let matches = match cli::build_cli().try_get_matches_from(&args) {
        Ok(m) => m,
        Err(e) => {
            if let Some(msg) = cli::fixup_error(&e, &bin_name) {
                eprint!("{msg}");
                std::process::exit(2);
            }
            e.exit();
        }
    };
    install_panic_hook();
    msg::set_verbose(matches.get_flag("verbose"));
    let json = matches
        .get_one::<String>("output_format")
        .map(|s| s == "json")
        .unwrap_or(false);
    JSON_OUTPUT.store(json, Ordering::SeqCst);

    let result: Result<(), Diag> = match matches.subcommand() {
        Some(("build", sub)) => build::run_build(build::BuildArgs {
            config_path: sub.get_one::<String>("config_path").cloned(),
            json_only: sub.get_flag("json_only"),
        }),
        Some(("dev", sub)) => dev::run_dev(dev::DevArgs {
            port: sub.get_one::<u16>("port").copied(),
            config_path: sub.get_one::<String>("config_path").cloned(),
            no_first_build: sub.get_flag("no_first_build"),
            include_paths: sub
                .get_many::<String>("include_paths")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
        }),
        Some(("serve", sub)) => serve::run_serve(*sub.get_one::<u16>("port").unwrap_or(&7979)),
        Some(("generate", sub)) => match sub.subcommand() {
            Some(("ci", ci)) => generate::run_ci(generate::CiArgs {
                output_path: ci.get_one::<String>("output_path").cloned(),
                site_path: ci.get_one::<String>("site_path").cloned(),
            }),
            _ => Ok(()),
        },
        Some(("config-schema", sub)) => schema::run(sub.get_one::<String>("output").cloned()),
        Some(("generate-css", sub)) => css::run_generate_css(sub.get_one::<String>("out_dir").cloned()),
        _ => Ok(()),
    };
    if let Err(d) = result {
        fatal(&d);
    }
}
