//! The `build` command.

use crate::artifacts;
use crate::config::{Config, OrandaLayer, WorkspaceConfig};
use crate::msg;
use crate::net;
use crate::project::{self, json_error_diag};
use crate::report::Diag;
use crate::repo::GithubRepo;
use std::path::{Path, PathBuf};

pub struct BuildArgs {
    pub config_path: Option<String>,
    pub json_only: bool,
}

pub const WORKSPACE_CONFIG: &str = "./oranda-workspace.json";
pub const DEFAULT_CONFIG: &str = "./oranda.json";

static FAVICON: &[u8] = include_bytes!("../assets/favicon.ico");
pub static ARTIFACTS_JS: &[u8] = include_bytes!("../assets/artifacts.js");

/// Read and parse an oranda config layer. Returns `Ok(None)` if the file
/// doesn't exist.
pub fn load_layer(path: &Path, display: &str) -> Result<Option<OrandaLayer>, Diag> {
    if !path.exists() {
        return Ok(None);
    }
    let contents = match std::fs::read(path) {
        Ok(c) => String::from_utf8_lossy(&c).to_string(),
        Err(e) => {
            return Err(Diag::error(format!("failed to read asset from {display}"))
                .with_cause(e.to_string()))
        }
    };
    match serde_json::from_str::<OrandaLayer>(&contents) {
        Ok(l) => Ok(Some(l)),
        Err(e) => Err(json_error_diag(display, &contents, &e)),
    }
}

pub struct SiteSpec {
    pub config: Config,
    pub prefix: Option<String>,
    pub root: PathBuf,
}

/// Load the configuration for a site rooted at `root`.
pub fn load_config(
    config_path: &Path,
    config_display: &str,
    root: &Path,
    base: Option<&OrandaLayer>,
    prefix: Option<&str>,
) -> Result<(Config, crate::project::ProjectInfo), Diag> {
    let custom = load_layer(config_path, config_display)?;
    if custom.is_none() {
        msg::debug("No config found, using default values", prefix);
    }
    let info = project::detect(root);
    let mut cfg = Config::default();
    if let Some(p) = &info.layer {
        cfg.apply_project(p);
    }
    if info.cargo_dist {
        if let Some(a) = cfg.components.artifacts.as_mut() {
            a.cargo_dist = true;
        }
    }
    if let Some(b) = base {
        cfg.apply_layer(b);
    }
    if let Some(c) = &custom {
        cfg.apply_layer(c);
    }
    Ok((cfg, info))
}

fn clean_dist_dir(dist: &str) -> Result<(), Diag> {
    let p = Path::new(dist);
    if p.exists() {
        if let Err(e) = std::fs::remove_dir_all(p) {
            return Err(Diag::error(e.to_string()));
        }
    }
    if let Err(e) = std::fs::create_dir_all(p) {
        return Err(Diag::error(e.to_string()));
    }
    Ok(())
}

pub fn write_favicon(dist: &str) -> Result<(), Diag> {
    let dest = Path::new(dist).join("favicon.ico");
    if let Err(e) = std::fs::write(&dest, FAVICON) {
        return Err(Diag::error(format!(
            "failed to write asset from favicon.ico to {}.",
            dest.display()
        ))
        .with_cause(e.to_string())
        .with_help("Make sure your path is relative to your oranda config or project manifest file."));
    }
    Ok(())
}

/// Fetch the oranda CSS for the given version.
pub fn fetch_css(version: &str) -> Result<Vec<u8>, Diag> {
    let proxy = format!("https://octolotl.axodotdev.host/downloads/axodotdev/oranda/{version}/oranda.css");
    let gh = format!("https://api.github.com/repos/axodotdev/oranda/releases/download/{version}/oranda.css");
    match net::get_with_proxy_fallback(&proxy, &gh) {
        Ok(b) => Ok(b),
        Err(e) => Err(Diag::error(e.message()).with_causes(e.causes())),
    }
}

pub struct Context {
    pub releases_found: bool,
}

/// Fetch release information for the configured repository.
fn build_context(cfg: &Config) -> Result<Option<Context>, Diag> {
    let repo_url = match &cfg.project.repository {
        Some(r) => r.clone(),
        None => return Ok(None),
    };
    let wants_releases = cfg.components.artifacts_enabled() || cfg.components.changelog_enabled();
    if wants_releases {
        let repo = match GithubRepo::from_url(&repo_url) {
            Ok(r) => r,
            Err(e) => {
                crate::print_diag(&e.to_diag());
                return Ok(Some(Context {
                    releases_found: false,
                }));
            }
        };
        if let Err(e) = fetch_releases(&repo) {
            let d = Diag::error("Failed fetching releases from Github.")
                .with_cause(e.message())
                .with_causes(e.causes());
            crate::print_diag(&d);
        }
        Ok(Some(Context {
            releases_found: false,
        }))
    } else {
        let repo = match GithubRepo::from_url(&repo_url) {
            Ok(r) => r,
            Err(e) => return Err(e.to_diag()),
        };
        if fetch_releases(&repo).is_err() {
            let d = Diag::warning(format!(
                "Failed checking for Github releases for repo, ({}/{}). Proceeding without releases...",
                repo.owner, repo.name
            ));
            crate::print_diag(&d);
        }
        Ok(Some(Context {
            releases_found: false,
        }))
    }
}

fn fetch_releases(repo: &GithubRepo) -> Result<Vec<u8>, net::NetError> {
    let proxy = format!(
        "https://octolotl.axodotdev.host/releases/{}/{}",
        repo.owner, repo.name
    );
    let gh = format!(
        "https://api.github.com/repos/{}/{}/releases",
        repo.owner, repo.name
    );
    net::get_with_proxy_fallback(&proxy, &gh)
}

/// Build a single site. `workspace_member` controls workspace specific
/// output (the artifacts script).
pub fn build_site(cfg: &Config, json_only: bool, prefix: Option<&str>, workspace_member: bool) -> Result<(), Diag> {
    let dist = cfg.build.dist_dir.clone();
    clean_dist_dir(&dist)?;
    if !json_only {
        if cfg.styles.favicon.is_none() {
            write_favicon(&dist)?;
        }
        fetch_css(&cfg.styles.oranda_css_version)?;
        // Without the CSS we cannot continue rendering pages; the fetch
        // above always fails in this implementation.
        return Ok(());
    }
    let context = build_context(cfg)?;
    let mut artifacts_json: Option<String> = None;
    if let (Some(ctx), Some(art)) = (&context, &cfg.components.artifacts) {
        if art.has_some() && !ctx.releases_found && !art.match_package_names {
            msg::warning("You seem to have release automation set up, but we didn't detect any releases. The install page and associated widget will be empty. To disable this, set `artifacts: false`", prefix);
            artifacts_json = Some(artifacts::current_release_json(
                art,
                cfg.build.path_prefix.as_deref(),
            ));
        }
    }
    if workspace_member {
        let dest = Path::new(&dist).join("artifacts.js");
        write_file(&dest, ARTIFACTS_JS)?;
    }
    if let Some(j) = artifacts_json {
        let dest = Path::new(&dist).join("artifacts.json");
        write_file(&dest, j.as_bytes())?;
    }
    Ok(())
}

pub fn write_file(dest: &Path, data: &[u8]) -> Result<(), Diag> {
    if let Err(e) = std::fs::write(dest, data) {
        return Err(Diag::error(format!(
            "failed to write a new asset to {}.",
            dest.display()
        ))
        .with_cause(e.to_string())
        .with_help("Make sure you have the correct permissions to create a new file."));
    }
    Ok(())
}

fn join_prefix(base: Option<&str>, slug: &str) -> String {
    match base {
        Some(b) => {
            let b = b.trim_end_matches('/');
            if b.is_empty() {
                slug.to_string()
            } else {
                format!("{b}/{slug}")
            }
        }
        None => slug.to_string(),
    }
}

pub fn run_build(args: BuildArgs) -> Result<(), Diag> {
    let ws_path = Path::new(WORKSPACE_CONFIG);
    if ws_path.exists() {
        return run_workspace_build(&args);
    }
    let (config_path, display) = match &args.config_path {
        Some(p) => (PathBuf::from(p), p.clone()),
        None => (PathBuf::from(DEFAULT_CONFIG), DEFAULT_CONFIG.to_string()),
    };
    let (cfg, _info) = load_config(&config_path, &display, Path::new("."), None, None)?;
    build_site(&cfg, args.json_only, None, false)?;
    msg::success(&format!(
        "Your site build is located in `{}`.",
        cfg.build.dist_dir
    ));
    Ok(())
}

pub struct WorkspaceMemberSite {
    pub slug: String,
    pub config: Config,
}

/// Load the workspace and all of its members.
pub fn load_workspace() -> Result<(Config, WorkspaceConfig, Vec<WorkspaceMemberSite>), Diag> {
    let ws_layer = load_layer(Path::new(WORKSPACE_CONFIG), WORKSPACE_CONFIG)?.unwrap_or_default();
    msg::info("Workspace detected, gathering info...");
    let mut ws_cfg = Config::default();
    ws_cfg.apply_layer(&ws_layer);
    let ws = WorkspaceConfig::from_layer(ws_layer.workspace.as_ref());
    let mut members_list = ws.members.clone();
    if ws.auto {
        let info = project::detect(Path::new("."));
        for m in info.members {
            if !members_list.iter().any(|x| x.slug == m.slug) {
                members_list.push(m);
            }
        }
    }
    let cwd = std::env::current_dir().unwrap_or_default();
    let mut members = Vec::new();
    // the base layer for members excludes the workspace section
    let mut base = ws_layer.clone();
    base.workspace = None;
    for m in &members_list {
        let member_dir = project::normalize(&cwd.join(&m.path));
        if !member_dir.is_dir() {
            return Err(Diag::error(format!(
                "failed to read workspace member at {}",
                m.path
            )));
        }
        let cfg_path = member_dir.join("oranda.json");
        let display = cfg_path.display().to_string();
        let (mut cfg, _info) = load_config(&cfg_path, &display, &member_dir, Some(&base), Some(&m.slug))?;
        cfg.build.dist_dir = Path::new(&ws_cfg.build.dist_dir)
            .join(&m.slug)
            .display()
            .to_string();
        cfg.build.path_prefix = Some(join_prefix(ws_cfg.build.path_prefix.as_deref(), &m.slug));
        members.push(WorkspaceMemberSite {
            slug: m.slug.clone(),
            config: cfg,
        });
    }
    Ok((ws_cfg, ws, members))
}

fn run_workspace_build(args: &BuildArgs) -> Result<(), Diag> {
    let (ws_cfg, ws, members) = load_workspace()?;
    msg::info(&format!("Building {} workspace member(s)...", members.len()));
    let cwd = std::env::current_dir().unwrap_or_default();
    for m in &members {
        build_site(&m.config, args.json_only, Some(&m.slug), true)?;
        let _ = std::env::set_current_dir(&cwd);
    }
    if ws.generate_index && !args.json_only {
        msg::info("Building workspace index page...");
        let dist = ws_cfg.build.dist_dir.clone();
        if ws_cfg.styles.favicon.is_none() {
            write_favicon(&dist)?;
        }
        fetch_css(&ws_cfg.styles.oranda_css_version)?;
    }
    msg::success(&format!(
        "Your site builds are located in `{}`.",
        ws_cfg.build.dist_dir
    ));
    Ok(())
}
