fn binary_works(bin: &std::path::Path) -> bool {
    Command::new(bin)
        .arg("--help")
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .is_ok()
}

pub fn run_generate_css(out_dir: Option<String>) -> Result<(), Diag> {
    let cache = cache_dir().map(|c| c.join("oranda"));
    if let Some(c) = &cache {
        let _ = std::fs::create_dir_all(c);
    }
    let binary: PathBuf;
    if binary_works(std::path::Path::new("tailwindcss")) {
        msg::info("Found Tailwind binary on the path!");
        binary = PathBuf::from("tailwindcss");
    } else {
        let cached = cache.as_ref().map(|c| c.join("tailwindcss"));
        match cached {
            Some(p) if p.exists() => {
                binary = p;
            }
            _ => {
                msg::info("Couldn't find Tailwind binary");
                msg::info("Fetching Tailwind binary from GitHub release...");
                let url = format!(
