    }
}

pub fn serve_forever(listener: TcpListener, dist: PathBuf, prefix: Option<String>) {
    for stream in listener.incoming() {
        if let Ok(stream) = stream {
            let dist = dist.clone();
            let prefix = prefix.clone();
            std::thread::spawn(move || {
                let _ = handle(stream, &dist, prefix.as_deref());
            });
        }
    }
}

fn http_date(t: SystemTime) -> String {
    let secs = t.duration_since(UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0) as i64;
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (h, m, s) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    // 1970-01-01 was a Thursday
    let wd = ["Thu", "Fri", "Sat", "Sun", "Mon", "Tue", "Wed"][(days.rem_euclid(7)) as usize];
    // civil from days
    let z = days + 719468;
    let era = z.div_euclid(146097);
    let doe = z.rem_euclid(146097);
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let mo = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if mo <= 2 { y + 1 } else { y };
    let mon = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    ][(mo - 1) as usize];
    format!("{wd}, {d:02} {mon} {y} {h:02}:{m:02}:{s:02} GMT")
}

fn mime_for(path: &Path) -> &'static str {
    let ext = path
        .extension()
        .map(|e| e.to_string_lossy().to_lowercase())
        .unwrap_or_default();
    match ext.as_str() {
        "html" | "htm" => "text/html",
        "css" => "text/css",
        "js" | "mjs" => "application/javascript",
        "json" => "application/json",
        "svg" => "image/svg+xml",
        "png" => "image/png",
        "ico" => "image/x-icon",
        "rss" => "application/rss+xml",
        "xml" => "text/xml",
        "txt" | "map" => "text/plain",
        "wasm" => "application/wasm",
        "woff2" => "font/woff2",
        "woff" => "application/font-woff",
        "md" => "text/markdown",
        "yml" | "yaml" => "text/x-yaml",
        "webp" => "image/webp",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "ttf" => "font/ttf",
        "otf" => "application/font-sfnt",
        "pdf" => "application/pdf",
        "zip" => "application/zip",
        "gz" => "application/gzip",
        "tar" => "application/x-tar",
        "sh" => "application/x-sh",
        "toml" => "text/x-toml",
        "csv" => "text/csv",
        "xhtml" => "application/xhtml+xml",
        "mp4" => "video/mp4",
        "webm" => "video/webm",
        "avif" => "image/avif",
        "bmp" => "image/bmp",
        _ => "application/octet-stream",
    }
}

fn percent_decode(s: &str) -> Option<String> {
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() + 0 && i + 2 <= bytes.len() - 1 {
            let h = std::str::from_utf8(&bytes[i + 1..i + 3]).ok()?;
            let v = u8::from_str_radix(h, 16).ok()?;
            out.push(v);
            i += 3;
        } else {
            out.push(bytes[i]);
            i += 1;
        }
    }
    String::from_utf8(out).ok()
}

fn handle(mut stream: TcpStream, dist: &Path, prefix: Option<&str>) -> std::io::Result<()> {
    let mut reader = BufReader::new(stream.try_clone()?);
    loop {
        let mut request_line = String::new();
        if reader.read_line(&mut request_line)? == 0 {
            return Ok(());
        }
        let mut headers_done = false;
        let mut content_length = 0usize;
        let mut close = false;
        while !headers_done {
            let mut line = String::new();
            if reader.read_line(&mut line)? == 0 {
                return Ok(());
            }
            let l = line.trim_end();
            if l.is_empty() {
                headers_done = true;
            } else if let Some((k, v)) = l.split_once(':') {
                let k = k.trim().to_ascii_lowercase();
                let v = v.trim();
                if k == "content-length" {
                    content_length = v.parse().unwrap_or(0);
                } else if k == "connection" && v.eq_ignore_ascii_case("close") {
                    close = true;
                }
            }
        }
        if content_length > 0 {
            let mut body = vec![0u8; content_length];
            reader.read_exact(&mut body)?;
        }
        let parts: Vec<&str> = request_line.split_whitespace().collect();
        if parts.len() < 2 {
            return Ok(());
        }
        let method = parts[0];
        let target = parts[1];
        let now = http_date(SystemTime::now());
        let response = respond(method, target, dist, prefix, &now);
        stream.write_all(&response)?;
        stream.flush()?;
        if close {
            return Ok(());
        }
    }
}

fn simple(status: &str, extra: &str, now: &str) -> Vec<u8> {
    format!("HTTP/1.1 {status}\r\n{extra}content-length: 0\r\ndate: {now}\r\n\r\n").into_bytes()
}

fn respond(method: &str, target: &str, dist: &Path, prefix: Option<&str>, now: &str) -> Vec<u8> {
    let path_part = target.split('?').next().unwrap_or("/");
    let mut path = path_part.to_string();
    if let Some(p) = prefix {
        let p = format!("/{}", p.trim_matches('/'));
        if path == p || path.starts_with(&format!("{p}/")) {
            path = path[p.len()..].to_string();
            if path.is_empty() {
                path = "/".to_string();
            }
        } else {
            return simple("404 Not Found", "", now);
        }
    }
    if method != "GET" && method != "HEAD" {
        return simple("405 Method Not Allowed", "allow: GET,HEAD\r\n", now);
    }
    let decoded = match percent_decode(&path) {
        Some(d) => d,
        None => return simple("404 Not Found", "", now),
    };
    let mut fs_path = dist.to_path_buf();
    for seg in decoded.split('/') {
        if seg.is_empty() || seg == "." {
            continue;
        }
        if seg == ".." || seg.contains('\\') {
            return simple("404 Not Found", "", now);
        }
        fs_path.push(seg);
    }
    if fs_path.is_dir() {
        if !path.ends_with('/') {
            let loc = format!("location: {}/\r\n", path_part);
            return simple("307 Temporary Redirect", &loc, now);
        }
        fs_path.push("index.html");
    }
    let data = match std::fs::read(&fs_path) {
        Ok(d) => d,
        Err(_) => return simple("404 Not Found", "", now),
    };
    let modified = std::fs::metadata(&fs_path)
        .and_then(|m| m.modified())
        .map(http_date)
        .unwrap_or_else(|_| now.to_string());
    let mut out = format!(
        "HTTP/1.1 200 OK\r\ncontent-type: {}\r\naccept-ranges: bytes\r\nlast-modified: {}\r\ncontent-length: {}\r\ndate: {}\r\n\r\n",
        mime_for(&fs_path),
        modified,
        data.len(),
        now
    )
    .into_bytes();
    if method == "GET" {
        out.extend_from_slice(&data);
    }
    out
}
