//! The `generate ci` command.

use crate::msg;
use crate::prompt;
use crate::report::Diag;
use std::path::Path;

pub struct CiArgs {
    pub output_path: Option<String>,
    pub site_path: Option<String>,
}

static CI_TEMPLATE: &str = include_str!("../assets/ci_base.yml");

const LINK_CHECK: &str = "      - name: Prepare HTML for link checking
        # untitaker/hyperlink supports no site prefixes, move entire site into
        # a subfolder
        run: mkdir /tmp/public/ && cp -R public /tmp/public/oranda

      - name: Check HTML for broken internal links
        uses: untitaker/hyperlink@0.1.29
        with:
          args: /tmp/public/

";

fn ask(question: &str, default: bool, help: Option<&str>) -> bool {
    match prompt::confirm(question, default, help) {
        Ok(v) => v,
        Err(e) => crate::panic_at(
            "src/generate.rs:56:14",
            format!("Error while prompting!: {e:?}"),
        ),
    }
}

pub fn run_ci(args: CiArgs) -> Result<(), Diag> {
    msg::info("Generating a CI deploy workflow for your site...");
    let link_check = ask(
        "Do you want to include a tool for checking generated hyperlinks?",
        true,
        Some("[Read more about the link checker tool: https://github.com/untitaker/hyperlink]"),
    );
    let latest = ask(
        "Do you want to always use the latest version of oranda?",
        false,
        Some("[Using the latest version means you don't have to rerun this command when oranda updates, but it may also break your site if you use a lot of configuration!]"),
    );
    let gitignore = ask(
        "Would you like to append the default destination directory (`public`) to your .gitignore file?",
        false,
        None,
    );

    let mut text = CI_TEMPLATE.to_string();
    if !link_check {
        text = text.replace(LINK_CHECK, "");
    }
    if latest {
        text = text.replace(
            "releases/download/v0.6.1/oranda-installer.sh",
            "releases/latest/download/oranda-installer.sh",
        );
    }
    if let Some(site) = &args.site_path {
        text = text.replace(
            "oranda-installer.sh | sh\n",
            &format!("oranda-installer.sh | sh\n          cd {site}\n"),
        );
    }
    let out = args
        .output_path
        .clone()
        .unwrap_or_else(|| ".github/workflows/web.yml".to_string());
    let out_path = Path::new(&out);
    if let Some(parent) = out_path.parent() {
        if !parent.as_os_str().is_empty() {
            if let Err(e) = std::fs::create_dir_all(parent) {
                return Err(Diag::error(format!(
                    "failed to create a new directory at {}.",
                    parent.display()
                ))
                .with_cause(e.to_string()));
            }
        }
    }
    crate::build::write_file(out_path, text.as_bytes())?;
    if gitignore {
        let gi = Path::new(".gitignore");
        let mut existing = std::fs::read(gi).unwrap_or_default();
        existing.extend_from_slice(b"\n# Generated by `oranda generate ci`\npublic/");
        crate::build::write_file(gi, &existing)?;
    }
    msg::success(&format!("Wrote CI file to {:?}", out));
    Ok(())
}
