cat > /workspace/src/dev.rs <<'EOF'
//! The `dev` command: build, serve and rebuild on changes.

use crate::build::{self, BuildArgs};
use crate::msg;
use crate::report::Diag;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime};

pub struct DevArgs {
    pub port: Option<u16>,
    pub config_path: Option<String>,
    pub no_first_build: bool,
    pub include_paths: Vec<String>,
}

fn normalize_rel(p: &str) -> String {
    let path = Path::new(p);
    let mut out = PathBuf::new();
    for c in path.components() {
        match c {
            std::path::Component::CurDir => {}
            other => out.push(other.as_os_str()),
        }
    }
    out.display().to_string()
}

fn path_not_found(p: &str) -> Diag {
    Diag::error(format!("Specified path `{p}` was not found on your filesystem!"))
        .with_help("Make sure you specify your path relative to the oranda.json/manifest file/README file of your project!")
}

fn find_mdbook(cfg: &crate::config::Config) -> Result<Option<(PathBuf, PathBuf)>, Diag> {
    let explicit = cfg.components.mdbook.as_ref().and_then(|m| m.path.clone());
    let dir: PathBuf;
    let display: String;
    if let Some(p) = explicit {
        if !Path::new(&p).exists() {
            return Err(path_not_found(&p));
        }
        let cwd = std::env::current_dir().unwrap_or_default();
        dir = crate::project::normalize(&cwd.join(&p));
        display = dir.display().to_string();
    } else {
        let candidates = ["./", "./book/", "./docs/"];
        let mut found = None;
        for c in candidates {
            if Path::new(c).join("book.toml").exists() {
                found = Some(c);
                break;
            }
        }
        match found {
            None => return Ok(None),
            Some("./") => {
                dir = PathBuf::new();
                display = String::new();
            }
            Some(c) => {
                let cwd = std::env::current_dir().unwrap_or_default();
                dir = crate::project::normalize(&cwd.join(c));
                display = dir.display().to_string();
            }
        }
    }
    let book_toml = dir.join("book.toml");
    let src_name = std::fs::read_to_string(if dir.as_os_str().is_empty() {
        PathBuf::from("book.toml")
    } else {
        book_toml.clone()
    })
    .ok()
    .and_then(|s| s.parse::<toml::Table>().ok())
    .and_then(|t| {
        t.get("book")
            .and_then(|b| b.get("src"))
            .and_then(|s| s.as_str())
            .map(|s| s.to_string())
    })
    .unwrap_or_else(|| "src".to_string());
    let src = dir.join(&src_name);
    let toml_text = std::fs::read_to_string(if dir.as_os_str().is_empty() {
        PathBuf::from("book.toml")
    } else {
        book_toml.clone()
    })
    .unwrap_or_default();
    if let Err(e) = toml_text.parse::<toml::Table>() {
        let msg = e.message().to_string();
        return Err(Diag::error(format!("Couldn't load your mdbook at {display}"))
            .with_cause("Invalid configuration file")
            .with_cause(msg));
    }
    let summary = if src.as_os_str().is_empty() {
        PathBuf::from("SUMMARY.md")
    } else {
        src.join("SUMMARY.md")
    };
    if let Err(e) = std::fs::read(&summary) {
        return Err(Diag::error(format!("Couldn't load your mdbook at {display}"))
            .with_cause(format!("Couldn't open SUMMARY.md in {:?} directory", src.display().to_string()))
            .with_cause(e.to_string()));
    }
    Ok(Some((book_toml, src)))
}

pub fn run_dev(args: DevArgs) -> Result<(), Diag> {
    let (config_path, display) = match &args.config_path {
        Some(p) => (PathBuf::from(p), p.clone()),
        None => (PathBuf::from(build::DEFAULT_CONFIG), build::DEFAULT_CONFIG.to_string()),
    };
    let (cfg, _) = build::load_config(&config_path, &display, Path::new("."), None, None)?;

    let mut paths: Vec<String> = Vec::new();
    let readme = cfg
        .project
        .readme_path
        .clone()
        .unwrap_or_else(|| "README.md".to_string());
    if Path::new(&readme).exists() {
        paths.push(readme);
    }
    let cfg_name = config_path
        .display()
        .to_string()
        .trim_start_matches("./")
        .to_string();
    if config_path.exists() {
        paths.push(cfg_name);
    }
    if let Some(f) = &cfg.components.funding {
        let yml = f.yml_path.clone().unwrap_or_else(|| ".github/FUNDING.yml".to_string());
        if Path::new(&yml).exists() {
            paths.push(yml);
        }
        let md = f.md_path.clone().unwrap_or_else(|| "funding.md".to_string());
        if Path::new(&md).exists() {
            paths.push(md);
        }
    } else if cfg.components.funding.is_none() && !funding_disabled(&config_path) {
        let yml = ".github/FUNDING.yml".to_string();
        if Path::new(&yml).exists() {
            paths.push(yml);
        }
        let md = "funding.md".to_string();
        if Path::new(&md).exists() {
            paths.push(md);
        }
    }
    for (_, page) in &cfg.build.additional_pages {
        if !Path::new(page).exists() {
            return Err(path_not_found(page));
        }
        paths.push(normalize_rel(page));
    }
    if let Some((book, src)) = find_mdbook(&cfg)? {
        paths.push(book.display().to_string());
        paths.push(src.display().to_string());
    }
    for p in &args.include_paths {
        if Path::new(p).exists() {
            paths.push(p.clone());
        }
    }
    msg::info(&format!("Found {} paths to watch, starting watch...", paths.len()));
    msg::debug(&format!("Files watched: {:?}", paths), None);

    let do_build = || -> Result<(), Diag> {
        build::run_build(BuildArgs {
            config_path: args.config_path.clone(),
            json_only: false,
        })
    };
    if !args.no_first_build {
        do_build()?;
    }

    let port = args.port.unwrap_or(7979);
    let prefix = cfg.build.path_prefix.clone();
    let url = match &prefix {
        Some(p) => format!("http://127.0.0.1:{port}/{p}"),
        None => format!("http://127.0.0.1:{port}"),
    };
    msg::success(&format!("Your project is available at: {url}"));
    let dist = cfg.build.dist_dir.clone();
    if !Path::new(&dist).exists() {
        crate::panic_at(
            "src/commands/dev.rs:131:62",
            format!(
                "called `Result::unwrap()` on an `Err` value: BuildNotFound {{ dist_dir: {:?} }}",
                dist
            ),
        );
    }
    let listener = crate::serve::bind(port)?;
    let dist_path = PathBuf::from(&dist);
    std::thread::spawn(move || crate::serve::serve_forever(listener, dist_path, prefix));

    let mut last = snapshot(&paths);
    loop {
        std::thread::sleep(Duration::from_millis(500));
        let now = snapshot(&paths);
        if now != last {
            last = now;
            if let Err(d) = do_build() {
                crate::print_diag(&d);
            }
        }
    }
}

fn funding_disabled(_p: &Path) -> bool {
    false
}

fn snapshot(paths: &[String]) -> Vec<Option<SystemTime>> {
    let mut out = Vec::new();
    for p in paths {
        let path = Path::new(p);
        if path.is_dir() {
            for entry in walk(path) {
                out.push(std::fs::metadata(&entry).and_then(|m| m.modified()).ok());
            }
        } else {
            out.push(std::fs::metadata(path).and_then(|m| m.modified()).ok());
        }
    }
    out
}

fn walk(dir: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(rd) = std::fs::read_dir(dir) {
        let mut entries: Vec<PathBuf> = rd.filter_map(|e| e.ok().map(|e| e.path())).collect();
        entries.sort();
        for e in entries {
            if e.is_dir() {
                out.extend(walk(&e));
            } else {
                out.push(e);
            }
        }
    }
    out
}
