/// The message Rust produces when slicing a string at a non char boundary.
fn slice_panic_message(s: &str, index: usize) -> String {
    const MAX_DISPLAY_LENGTH: usize = 256;
    let mut trunc_len = MAX_DISPLAY_LENGTH.min(s.len());
    while !s.is_char_boundary(trunc_len) {
        trunc_len -= 1;
    }
    let s_trunc = &s[..trunc_len];
    let ellipsis = if trunc_len < s.len() { "[...]" } else { "" };
    let mut char_start = index;
    while !s.is_char_boundary(char_start) {
        char_start -= 1;
    }
    let ch = s[char_start..].chars().next().unwrap_or(' ');
    format!(
        "byte index {} is not a char boundary; it is inside {:?} (bytes {:?}) of `{}`{}",
        index,
        ch,
        char_start..char_start + ch.len_utf8(),
        s_trunc,
        ellipsis
    )
}

