/// Collect the watch paths for a single site config.
fn site_paths(
    cfg: &crate::config::Config,
    config_path: &Path,
    config_display: &str,
    member_dir: Option<&Path>,
) -> Result<Vec<String>, Diag> {
    let mut paths: Vec<String> = Vec::new();
    let readme = cfg
        .project
        .readme_path
        .clone()
        .unwrap_or_else(|| "README.md".to_string());
    match member_dir {
        Some(dir) => {
            let p = dir.join(&readme);
            if p.exists() {
                paths.push(rel_to_cwd(&p));
            }
            if config_path.exists() {
                paths.push(rel_to_cwd(config_path));
            }
        }
        None => {
            if Path::new(&readme).exists() {
                paths.push(readme);
            }
            if config_path.exists() {
                paths.push(config_display.trim_start_matches("./").to_string());
            }
        }
    }
    if let Some(f) = &cfg.components.funding {
        let yml = f.yml_path.clone().unwrap_or_else(|| ".github/FUNDING.yml".to_string());
        if Path::new(&yml).exists() {
            paths.push(yml);
        }
        let md = f.md_path.clone().unwrap_or_else(|| "funding.md".to_string());
        if Path::new(&md).exists() {
            paths.push(md);
        }
    }
    for (_, page) in &cfg.build.additional_pages {
        let full = match member_dir {
            Some(dir) => dir.join(page),
            None => PathBuf::from(page),
        };
        if !full.exists() {
            return Err(path_not_found(page));
        }
        match member_dir {
            Some(_) => paths.push(rel_to_cwd(&crate::project::normalize(&full))),
            None => paths.push(normalize_rel(page)),
        }
    }
    if cfg.components.mdbook.is_some() {
        if let Some((book, src)) = find_mdbook(cfg)? {
            paths.push(book.display().to_string());
            paths.push(src.display().to_string());
        }
    }
    Ok(paths)
}

pub fn run_dev(args: DevArgs) -> Result<(), Diag> {
    let workspace = Path::new(build::WORKSPACE_CONFIG).exists();
    let mut paths: Vec<String> = Vec::new();
    let cfg;
    if workspace {
        let (ws_cfg, _ws, members) = build::load_workspace_inner(true)?;
        for m in &members {
            let cfg_path = m.dir.join("oranda.json");
            let display = cfg_path.display().to_string();
            paths.extend(site_paths(&m.config, &cfg_path, &display, Some(&m.dir))?);
        }
        paths.push("oranda-workspace.json".to_string());
        cfg = ws_cfg;
    } else {
        let (config_path, display) = match &args.config_path {
            Some(p) => (PathBuf::from(p), p.clone()),
            None => (PathBuf::from(build::DEFAULT_CONFIG), build::DEFAULT_CONFIG.to_string()),
        };
        let (c, _) = build::load_config(&config_path, &display, Path::new("."), None, None)?;
        paths.extend(site_paths(&c, &config_path, &display, None)?);
        cfg = c;
    }
    for p in &args.include_paths {
        if Path::new(p).exists() {
            paths.push(p.clone());
        }
    }
    msg::info(&format!("Found {} paths to watch, starting watch...", paths.len()));
    msg::debug(&format!("Files watched: {:?}", paths), None);

