//! Minimal interactive yes/no prompts.

use std::io::{BufRead, IsTerminal, Write};

pub enum PromptError {
    NotTty,
    Io(String),
}

impl std::fmt::Debug for PromptError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            PromptError::NotTty => write!(f, "NotTTY"),
            PromptError::Io(e) => write!(f, "IO({e})"),
        }
    }
}

fn term_cols() -> usize {
    terminal_size::terminal_size_of_fd(1)
        .or_else(|| terminal_size::terminal_size_of_fd(2))
        .map(|(w, _)| w.0 as usize)
        .filter(|w| *w > 0)
        .unwrap_or(80)
}

fn rows_for(text: &str, cols: usize) -> usize {
    let w = crate::textwrap::display_width(text);
    if w == 0 {
        1
    } else {
        w.div_ceil(cols)
    }
}

/// Ask a yes/no question. `default` is used when the user just hits enter.
pub fn confirm(question: &str, default: bool, help: Option<&str>) -> Result<bool, PromptError> {
    if !std::io::stdin().is_terminal() {
        return Err(PromptError::NotTty);
    }
    let hint = if default { "(Y/n)" } else { "(y/N)" };
    let mut out = std::io::stdout();
    let stdin = std::io::stdin();
    let cols = term_cols();
    loop {
        let prompt = format!("? >o_o< {question} {hint} ");
        let _ = write!(out, "{prompt}");
        if let Some(h) = help {
            let help_rows = rows_for(h, cols);
            let prompt_w = crate::textwrap::display_width(&prompt);
            let col = prompt_w % cols;
            let _ = write!(out, "\n{h}\x1b[{help_rows}A\r");
            if col > 0 {
                let _ = write!(out, "\x1b[{col}C");
            }
        }
        let _ = out.flush();
        let mut line = String::new();
        match stdin.lock().read_line(&mut line) {
            Ok(0) => return Err(PromptError::Io("unexpected end of input".to_string())),
            Ok(_) => {}
            Err(e) => return Err(PromptError::Io(e.to_string())),
        }
        let typed = line.trim_end_matches(['\n', '\r']);
        let used_rows = rows_for(&format!("{prompt}{typed}"), cols);
        let _ = write!(out, "\x1b[{used_rows}A\r\x1b[J");
