            "y" | "yes" => Some(true),
            "n" | "no" => Some(false),
            _ => None,
        };
        if let Some(v) = value {
            let _ = writeln!(out, "> {question} {}", if v { "Yes" } else { "No" });
            let _ = out.flush();
            return Ok(v);
        }
    }
}
