//! Minimal interactive yes/no prompts (rendered in raw terminal mode).

use std::io::{IsTerminal, Read, Write};

pub enum PromptError {
    NotTty,
    Interrupted,
    Canceled,
    Io(String),
}

impl std::fmt::Debug for PromptError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            PromptError::NotTty => write!(f, "NotTTY"),
            PromptError::Interrupted => write!(f, "OperationInterrupted"),
            PromptError::Canceled => write!(f, "OperationCanceled"),
            PromptError::Io(e) => write!(f, "IO({e})"),
        }
    }
}

fn term_cols() -> usize {
    terminal_size::terminal_size_of_fd(1)
        .or_else(|| terminal_size::terminal_size_of_fd(0))
        .map(|(w, _)| w.0 as usize)
        .filter(|w| *w > 0)
        .unwrap_or(80)
}

fn rows_for(text: &str, cols: usize) -> usize {
    let w = crate::textwrap::display_width(text);
    if w == 0 {
        1
    } else {
        w.div_ceil(cols)
    }
}

struct RawMode {
    original: libc::termios,
}

impl RawMode {
    fn enable() -> Option<RawMode> {
        unsafe {
            let mut t: libc::termios = std::mem::zeroed();
            if libc::tcgetattr(0, &mut t) != 0 {
                return None;
            }
            let original = t;
            t.c_lflag &= !(libc::ICANON | libc::ECHO | libc::ISIG | libc::IEXTEN);
            t.c_iflag &= !(libc::IXON | libc::ICRNL);
            t.c_cc[libc::VMIN] = 1;
            t.c_cc[libc::VTIME] = 0;
            if libc::tcsetattr(0, libc::TCSANOW, &t) != 0 {
                return None;
            }
            Some(RawMode { original })
        }
    }
}

impl Drop for RawMode {
    fn drop(&mut self) {
        unsafe {
            libc::tcsetattr(0, libc::TCSANOW, &self.original);
        }
    }
}

const INVALID: &str = "# Invalid answer, try typing 'y' for yes or 'n' for no";

/// Ask a yes/no question. `default` is used when the user just hits enter.
pub fn confirm(question: &str, default: bool, help: Option<&str>) -> Result<bool, PromptError> {
    if !std::io::stdin().is_terminal() {
        return Err(PromptError::NotTty);
    }
    let hint = if default { "(Y/n)" } else { "(y/N)" };
    let prompt = format!("? >o_o< {question} {hint} ");
    let mut out = std::io::stdout();
    let cols = term_cols();
    let raw = RawMode::enable();
    let mut input = String::new();
    let mut error = false;
    // rows between the start of the rendered block and the cursor row
    let mut cursor_rows = 0usize;

    let render = |out: &mut std::io::Stdout, input: &str, error: bool, cursor_rows: &mut usize| {
        let mut s = String::new();
        if *cursor_rows > 0 {
            s.push_str(&format!("\x1b[{}A", *cursor_rows));
        }
        s.push_str("\r\x1b[J");
        let mut rows = 0;
        if error {
            s.push_str(INVALID);
            s.push_str("\r\n");
            rows += rows_for(INVALID, cols);
        }
        let line = format!("{prompt}{input}");
        s.push_str(&line);
        let line_w = crate::textwrap::display_width(&line);
        rows += (line_w / cols.max(1)).min(rows_for(&line, cols));
        if let Some(h) = help {
            s.push_str("\r\n");
            s.push_str(h);
            let help_rows = rows_for(h, cols);
            s.push_str(&format!("\x1b[{help_rows}A\r"));
            let col = line_w % cols.max(1);
            if col > 0 {
                s.push_str(&format!("\x1b[{col}C"));
            }
        }
        *cursor_rows = rows;
        let _ = out.write_all(s.as_bytes());
        let _ = out.flush();
    };

    render(&mut out, &input, error, &mut cursor_rows);
    let mut stdin = std::io::stdin();
    let mut buf = [0u8; 1];
    let mut pending: Vec<u8> = Vec::new();
    loop {
        let n = match stdin.read(&mut buf) {
            Ok(n) => n,
            Err(e) => return Err(PromptError::Io(e.to_string())),
        };
        if n == 0 {
            return Err(PromptError::Io("unexpected end of input".to_string()));
        }
        let b = buf[0];
        match b {
            b'\r' | b'\n' => {
                let answer = input.trim().to_lowercase();
                let value = if input.is_empty() {
                    Some(default)
                } else {
                    match answer.as_str() {
                        "y" | "yes" => Some(true),
                        "n" | "no" => Some(false),
                        _ => None,
                    }
                };
                match value {
                    Some(v) => {
                        let mut s = String::new();
                        if cursor_rows > 0 {
                            s.push_str(&format!("\x1b[{cursor_rows}A"));
                        }
                        s.push_str("\r\x1b[J");
                        s.push_str(&format!("> {question} {}\r\n", if v { "Yes" } else { "No" }));
                        let _ = out.write_all(s.as_bytes());
                        let _ = out.flush();
                        drop(raw);
                        return Ok(v);
                    }
                    None => {
                        error = true;
                        render(&mut out, &input, error, &mut cursor_rows);
                    }
                }
            }
            3 => {
                drop(raw);
                let _ = writeln!(out);
                return Err(PromptError::Interrupted);
            }
            27 => {
                drop(raw);
                let _ = writeln!(out);
                return Err(PromptError::Canceled);
            }
            127 | 8 => {
                input.pop();
                render(&mut out, &input, error, &mut cursor_rows);
            }
            _ => {
                pending.push(b);
                if let Ok(s) = std::str::from_utf8(&pending) {
                    let s = s.to_string();
                    pending.clear();
                    if !s.chars().any(|c| c.is_control()) {
                        input.push_str(&s);
                        render(&mut out, &input, error, &mut cursor_rows);
                    }
                } else if pending.len() >= 4 {
                    pending.clear();
                }
            }
        }
    }
}
