fn skip_ansi_escape_sequence<I: Iterator<Item = char>>(ch: char, chars: &mut I) -> bool {
    if ch == '\\u{1b}' && chars.next() == Some('[') {
        for c in chars {
            if ('\\u{40}'..='\\u{7e}').contains(&c) {
                return true;
            }
        }
    }
    false
