/// Display width of a string, ignoring ANSI escape sequences.
pub fn display_width(s: &str) -> usize {
    let mut chars = s.chars();
    let mut width = 0;
    while let Some(ch) = chars.next() {
        if skip_ansi_escape_sequence(ch, &mut chars) {
            continue;
        }
        width += ch_width(ch);
    }
    width
}

