/// Rewrites clap's usage line for "similar argument" suggestions so that it
/// renders the whole argument group, like the original tool does. Returns
/// the message with ANSI styling (to be printed through a color-aware
/// stream).
pub fn fixup_error(err: &clap::Error, bin_name: &str) -> Option<String> {
    use clap::error::{ContextKind, ContextValue, ErrorKind};
    if err.kind() != ErrorKind::UnknownArgument {
        return None;
    }
    let suggested = match err.get(ContextKind::SuggestedArg) {
        Some(ContextValue::String(s)) => s.clone(),
        _ => return None,
    };
    let rendered = err.render().ansi().to_string();
    let prefix = format!("Usage: {bin_name}");
    let mut out = String::new();
    let mut changed = false;
    for line in rendered.split_inclusive('\\n') {
        let plain = strip_ansi(line);
        if let Some(rest) = plain.strip_prefix(&prefix) {
            let rest_trim = rest.trim_end_matches('\\n');
            let mut path: Vec<&str> = Vec::new();
            for cand in [
                " generate ci",
                " generate-css",
                " generate",
                " build",
                " dev",
                " serve",
                " config-schema",
            ] {
                if let Some(after) = rest_trim.strip_prefix(cand) {
                    if after.is_empty() || after.starts_with(' ') {
                        path = cand.trim().split(' ').collect();
                        break;
                    }
                }
            }
            if let Some(usage) = group_usage(&path, &suggested) {
                let has_subcommands = path.is_empty() || path == ["generate"];
                let mut cmd = bin_name.to_string();
                for p in &path {
                    cmd.push(' ');
                    cmd.push_str(p);
                }
                let mut new_line = format!("\\x1b[1m\\x1b[4mUsage:\\x1b[0m \\x1b[1m{cmd}\\x1b[0m {usage}");
                if has_subcommands {
                    new_line.push_str(" <COMMAND>");
                }
                new_line.push('\\n');
                out.push_str(&new_line);
                changed = true;
                continue;
            }
        }
        out.push_str(line);
    }
    if changed {
        Some(out)
    } else {
        None
    }
}
