/// Interpret an npm-style repository string (e.g. `github:owner/repo`,
/// `owner/repo` or `git+https://github.com/owner/repo.git`) as a hosted git
/// repository, returning a canonical https URL.
fn hosted_git_url(spec: &str) -> Option<String> {
    let main = spec.split('#').next().unwrap_or("");
    let render = |provider: &str, owner: &str, repo: &str| {
        format!("https://{provider}.com/{owner}/{repo}.git")
    };
    // URL forms
    for scheme in ["git+ssh://", "git+https://", "git+http://", "git://", "ssh://"] {
        if let Some(rest) = main.strip_prefix(scheme) {
            let first_sep = rest.find(['/', ':']).unwrap_or(rest.len());
            let rest = match rest[..first_sep].rfind('@') {
                Some(i) => &rest[i + 1..],
                None => match rest.find('@') {
                    Some(i) if i < rest.find('/').unwrap_or(rest.len()) => &rest[i + 1..],
                    _ => rest,
                },
            };
            let sep = rest.find(['/', ':'])?;
            let host = &rest[..sep];
            let path = &rest[sep + 1..];
            let provider = match host {
                "github.com" => "github",
                "gitlab.com" => "gitlab",
                "bitbucket.org" => "bitbucket",
                _ => return None,
            };
            let parts: Vec<&str> = path.split('/').collect();
            if parts.len() != 2 || parts[0].is_empty() || parts[1].is_empty() {
                return None;
            }
            let repo = parts[1].strip_suffix(".git").unwrap_or(parts[1]);
            return Some(render(provider, parts[0], repo));
        }
    }
    // provider shorthand
    if let Some((prov, rest)) = main.split_once(':') {
        let provider = match prov.to_ascii_lowercase().as_str() {
            "github" => "github",
            "gitlab" => "gitlab",
            "bitbucket" => "bitbucket",
            _ => return None,
        };
        let (owner, repo) = rest.split_once('/')?;
        if owner.is_empty() {
            return None;
        }
        return Some(render(provider, owner, repo));
    }
    // github shorthand: owner/repo
    let (owner, repo) = main.split_once('/')?;
    if owner.is_empty() || owner.starts_with('@') || main.contains(char::is_whitespace) && owner.contains(' ') {
        return None;
    }
    Some(render("github", owner, repo))
}
